(function(){
  if(new URLSearchParams(location.search).get('force')==='1')return;

  const ua=navigator.userAgent;
  const isMobile=
    /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(ua)||
    ('ontouchstart' in window&&navigator.maxTouchPoints>0);

  if(!isMobile)return;

  document.documentElement.dataset.duelsMobile='true';

  const overlay=document.createElement('div');
  overlay.id='duels3-mobile-warning';
  overlay.style.cssText=
    'position:fixed;inset:0;z-index:2147483647;display:flex;align-items:center;justify-content:center;background:#0a0a0c;';

  const content=document.createElement('div');
  content.style.cssText=
    'text-align:center;color:#adf;font-family:var(--font-ui);padding:40px;max-width:420px;';

  content.innerHTML=
    '<div style="font-size:2em;letter-spacing:4px;color:#f44;margin-bottom:24px;">⚠ 플레이 불가</div>'
    +'<div style="font-size:.9em;color:#778;letter-spacing:2px;line-height:2.4;">'
    +'이 게임은 PC에서만 플레이 가능합니다.<br>키보드와 마우스가 필요합니다.<br><br>'
    +'<span style="color:#556;">This game requires keyboard & mouse.<br>Please play on a PC.</span>'
    +'</div>';

  const ignore=document.createElement('button');
  ignore.type='button';
  ignore.textContent='무시하고 접속합니다.';
  ignore.style.cssText=
    'margin-top:32px;padding:0;border:0;background:transparent;font-size:12px;color:#556;letter-spacing:2px;text-decoration:underline;text-underline-offset:3px;cursor:pointer;';
  ignore.addEventListener('click',()=>{
    overlay.remove();
  });

  content.appendChild(ignore);
  overlay.appendChild(content);
  document.body.appendChild(overlay);
})();

/* 설정 */
const DUELS3_CONFIG = Object.freeze({
  accountApiBase: 'https://duels-account-api.lyan5097gc.workers.dev',
  storageKeys: Object.freeze({
    lastAccountId: 'duels3.account.lastId.v1',
    session: 'duels3.account.session.v1',
    guestIdentity: 'duels3.guest.identity.v1',
    firebaseAccountCachePrefix: 'duels3.firebase.accountCache.v1.'
  })
});

/* 버전 상태 */
const DUELS3_RELEASE = {
  version: '',
  date: ''
};

/* 버전 적용 (notes: 패치노트 데이터) */
function applyDuels3Release(notes) {
  const version = String(notes?.version || '').trim();
  const date = String(notes?.date || '').trim();
  if (!version) throw new Error('패치노트에 version 값이 없습니다.');

  DUELS3_RELEASE.version = version;
  DUELS3_RELEASE.date = date;

  const meta = document.querySelector('meta[name="duels-version"]');
  if (meta) meta.content = version;

  document.querySelectorAll('[data-duels-version-text]').forEach(node => {
    const mode = node.dataset.duelsVersionText;
    node.textContent =
      mode === 'prefix-v-space' ? `v ${version}` :
      mode === 'prefix-v' ? `v${version}` :
      version;
  });

  document.querySelectorAll('[data-duels-version-only]').forEach(node => {
    node.textContent = version;
  });

  return version;
}

/* 패널 */
const PanelController = Object.freeze({
  panel(name){
    return name === 'help'
      ?document.getElementById('duels-help-panel')
      :name === 'patch'
        ?document.getElementById('duels-patch-panel')
        :name === 'settings'
          ?document.getElementById('duels-display-settings-panel')
          :null;
  },
  closeAll(except = '') {
    for (const name of ['help','patch','settings']) {
      if (name === except) continue;
      const panel=this.panel(name);
      if(panel)panel.hidden=true;
    }
  },
  toggle(name, forceOpen) {
    const panel=this.panel(name);
    if (!panel) return;

    const shouldOpen =
      typeof forceOpen === 'boolean'
        ?forceOpen
        :panel.hidden;

    if (shouldOpen) this.closeAll(name);
    panel.hidden = !shouldOpen;

    if (shouldOpen && name === 'help') {
      HelpTabs.open('how');
    }

    if (shouldOpen && name === 'patch') {
      PatchTabs.open('features');
      if (!duels3PatchNotesLoaded) duels3LoadPatchNotes();
    }

    if (shouldOpen && name === 'settings') {
      DisplaySettings.syncUi();
      ProfileSettingsUI.render();
    }
  }
});

const HelpTabs = Object.freeze({
  open(name) {
    document.querySelectorAll('[data-help-dodge-cost]').forEach(el => {
      el.textContent = String(GAME_DATA.dodge.cost);
    });
    const safe = ['how','controls','status'].includes(name) ? name : 'how';
    document.querySelectorAll('[data-help-tab]').forEach(el => el.classList.toggle('active', el.dataset.helpTab === safe));
    document.querySelectorAll('[data-help-page]').forEach(el => el.classList.toggle('active', el.dataset.helpPage === safe));
  }
});


/* 인게임 팁 */
const DUELS_TIPS_URLS=Object.freeze([
  'https://raw.githubusercontent.com/LyangNem/Duels/main/tip.json',
  'https://github.com/LyangNem/Duels/raw/refs/heads/main/tip.json',
  'https://cdn.jsdelivr.net/gh/LyangNem/Duels@main/tip.json'
]);
const DuelsTipService={
  tips:[],
  currentIndex:-1,
  normalize(source){
    const raw=Array.isArray(source)?source:source?.tips;
    if(!Array.isArray(raw))return [];
    return raw
      .map(item=>typeof item==='string'?item:(item&&typeof item==='object'?item.text:''))
      .map(text=>String(text||'').trim())
      .filter(Boolean);
  },
  render(message=''){
    const text=this.tips[this.currentIndex]||message||'';
    document.querySelectorAll('[data-duels-tip]').forEach(button=>{
      button.hidden=!text;
      const target=button.querySelector('[data-duels-tip-text]');
      if(target)target.textContent=text;
    });
  },
  selectedCharacterName(){
    const selectedCard=
      document.querySelector(
        '#scr-between:not(.hidden) #between-char-grid .char-card.sel[data-id]'
      )||
      document.querySelector(
        '#scr-select:not(.hidden) .char-card.sel[data-id]'
      );
    const id=String(selectedCard?.dataset?.id||'').trim();
    if(!id)return '';
    const character=GAME_DATA?.characters?.[id]||null;
    return String(character?.name||'').trim();
  },
  randomIndex(indices){
    const pool=(Array.isArray(indices)?indices:[])
      .filter(index=>Number.isInteger(index)&&index>=0&&index<this.tips.length);
    if(!pool.length)return -1;
    const alternatives=pool.filter(index=>index!==this.currentIndex);
    const source=alternatives.length?alternatives:pool;
    return source[Math.floor(Math.random()*source.length)];
  },
  next(){
    const length=this.tips.length;
    if(!length){this.currentIndex=-1;this.render();return;}
    if(length===1){this.currentIndex=0;this.render();return;}

    let next=-1;
    const characterName=this.selectedCharacterName();
    if(characterName&&Math.random()<0.2){
      const characterTips=[];
      for(let index=0;index<length;index++){
        if(this.tips[index].includes(characterName))characterTips.push(index);
      }
      next=this.randomIndex(characterTips);
    }

    if(next<0){
      next=this.randomIndex(Array.from({length},(_,index)=>index));
    }
    this.currentIndex=next;
    this.render();
  },
  async fetchSource(url){
    const separator=url.includes('?')?'&':'?';
    const response=await fetch(`${url}${separator}t=${Date.now()}`,{
      cache:'no-store',
      mode:'cors',
      credentials:'omit'
    });
    if(!response.ok)throw new Error(`HTTP ${response.status}`);
    const text=(await response.text()).replace(/^\uFEFF/,'').trim();
    if(!text)throw new Error('EMPTY');
    const parsed=JSON.parse(text);
    const tips=this.normalize(parsed);
    if(!tips.length)throw new Error('NO TIPS');
    return tips;
  },
  async load(){
    this.tips=[];
    this.currentIndex=-1;
    this.render('팁 불러오는 중...');
    for(const url of DUELS_TIPS_URLS){
      try{
        this.tips=await this.fetchSource(url);
        this.next();
        return;
      }catch(error){
        console.warn('[DuelsTipService] tip.json load failed:',url,error);
      }
    }
    this.tips=[];
    this.currentIndex=-1;
    this.render('팁을 불러오지 못했습니다. 클릭해서 다시 시도');
  },
  bind(){
    document.querySelectorAll('[data-duels-tip]').forEach(button=>{
      button.addEventListener('click',()=>{
        if(this.tips.length)this.next();
        else this.load().catch(()=>{});
      });
    });
  }
};


/* 패치노트 */
const DUELS_PATCH_NOTES_URL='https://raw.githubusercontent.com/LyangNem/Duels/main/Patch-notes.json';
let duels3PatchNotesLoaded=false;

function duels3NormalizePatchNoteItem(item){
  if(typeof item==='string'){
    const change=item.trim();
    return change?{character:'',changes:[change]}:null;
  }
  if(!item||typeof item!=='object')return null;
  const character=String(item.character||item.characterName||item.target||item.name||'').trim();
  const rawChanges=item.changes??item.descriptions??item.items??item.description??item.text??item.change??item.details;
  const changes=(Array.isArray(rawChanges)?rawChanges:[rawChanges])
    .flatMap(value=>typeof value==='string'?value.split(/\r?\n/):[])
    .map(value=>value.replace(/^[-*•]\s*/, '').trim()).filter(Boolean);
  return changes.length?{character,changes}:null;
}
function duels3NormalizePatchNotes(source){
  const value=source&&typeof source==='object'?source:{};
  const list=(...keys)=>{
    for(const key of keys){
      const candidate=value[key];
      if(Array.isArray(candidate))return candidate.map(duels3NormalizePatchNoteItem).filter(Boolean);
      if(typeof candidate==='string')return candidate.split(/\r?\n/).map(item=>duels3NormalizePatchNoteItem(item.replace(/^[-*•]\s*/, '').trim())).filter(Boolean);
    }
    return [];
  };
  return {version:String(value.version||value.title||'').trim(),date:String(value.date||value.updatedAt||value.updated||'').trim(),features:list('features','additions','added','newFeatures'),balance:list('balance','balanceChanges','balancing'),bugfixes:list('bugfixes','bugFixes','fixes','bugs')};
}
function duels3ParsePatchNotesText(text){
  const result={version:'',date:'',features:[],balance:[],bugfixes:[]};
  let section='',currentGroup=null;
  String(text||'').split(/\r?\n/).forEach(raw=>{
    const line=raw.trim(); if(!line)return;
    const heading=line.replace(/^#+\s*/, '').replace(/[:：]$/, '').trim();
    if(/^(추가 기능|추가|신규 기능|features?|additions?)$/i.test(heading)){section='features';currentGroup=null;return;}
    if(/^(밸런스 조정|밸런스|balance(?: changes?)?)$/i.test(heading)){section='balance';currentGroup=null;return;}
    if(/^(버그 수정|버그|bug ?fixes?|fixes)$/i.test(heading)){section='bugfixes';currentGroup=null;return;}
    if(section){
      const m=line.match(/^>\s*(.+)$/);
      if(m&&section!=='features'){currentGroup={character:m[1].trim(),changes:[]};result[section].push(currentGroup);return;}
      const change=line.replace(/^[-*•]\s*/, '').trim();
      if(currentGroup&&section!=='features')currentGroup.changes.push(change); else result[section].push({character:'',changes:[change]});
    }else if(!result.version)result.version=heading;
  });
  return result;
}
function duels3RenderPatchNotesSection(containerId,items){
  const container=document.getElementById(containerId); if(!container)return;
  container.replaceChildren();
  const list=Array.isArray(items)?items:[];
  if(!list.length){const empty=document.createElement('li');empty.className='duels-patch-empty';empty.textContent='등록된 내용이 없습니다.';container.appendChild(empty);return;}
  list.forEach(raw=>{
    const entry=duels3NormalizePatchNoteItem(raw); if(!entry)return;
    const item=document.createElement('li');item.className=entry.character?'duels-patch-group':'duels-patch-single';
    if(entry.character){const character=document.createElement('div');character.className='duels-patch-character';character.textContent=entry.character;item.appendChild(character);}
    const changes=document.createElement('div');changes.className='duels-patch-changes';
    entry.changes.forEach(change=>{const description=document.createElement('div');description.className='duels-patch-description';description.textContent=change;changes.appendChild(description);});
    item.appendChild(changes);container.appendChild(item);
  });
}
function duels3RenderPatchNotes(notes){
  applyDuels3Release(notes);
  const meta=document.getElementById('duels-patch-meta');
  if(meta)meta.textContent=[DUELS3_RELEASE.version,DUELS3_RELEASE.date].filter(Boolean).join(' · ')||'LATEST PATCH';
  duels3RenderPatchNotesSection('duels-patch-features',notes.features);
  duels3RenderPatchNotesSection('duels-patch-balance',notes.balance);
  duels3RenderPatchNotesSection('duels-patch-bugfixes',notes.bugfixes);
  const state=document.getElementById('duels-patch-state');if(state)state.textContent='';
}
function duels3DescribePatchNoteJsonError(error,text){
  const message=String(error?.message||'JSON 문법 오류');const match=message.match(/position\s+(\d+)/i);
  if(!match)return `패치노트 JSON 문법 오류: ${message}`;
  const position=Math.max(0,Number(match[1])||0),before=String(text||'').slice(0,position),line=before.split(/\r?\n/).length,lastBreak=Math.max(before.lastIndexOf('\n'),before.lastIndexOf('\r')),column=position-lastBreak;
  return `패치노트 JSON 문법 오류: ${line}번째 줄 ${column}번째 칸`;
}
async function duels3LoadPatchNotes(forceReload=false){
  if(duels3PatchNotesLoaded&&!forceReload)return;
  const state=document.getElementById('duels-patch-state');if(state)state.textContent='패치노트를 불러오는 중...';
  try{
    const separator=DUELS_PATCH_NOTES_URL.includes('?')?'&':'?';
    const response=await fetch(`${DUELS_PATCH_NOTES_URL}${separator}t=${Date.now()}`,{cache:'no-store'});
    if(!response.ok)throw new Error(`HTTP ${response.status}`);
    const text=await response.text();let parsed;
    try{parsed=duels3NormalizePatchNotes(JSON.parse(text));}
    catch(parseError){const trimmed=text.trimStart();if(trimmed.startsWith('{')||trimmed.startsWith('['))throw new Error(duels3DescribePatchNoteJsonError(parseError,text));parsed=duels3ParsePatchNotesText(text);}
    duels3RenderPatchNotes(parsed);duels3PatchNotesLoaded=true;
  }catch(error){duels3PatchNotesLoaded=false;if(state)state.textContent=`패치노트를 불러오지 못했습니다. (${error.message||'NETWORK ERROR'})`;}
}
const PatchTabs=Object.freeze({
  open(name){
    const safe=['features','balance','bugfixes'].includes(name)?name:'features';
    document.querySelectorAll('[data-patch-tab]').forEach(el=>el.classList.toggle('active',el.dataset.patchTab===safe));
    document.querySelectorAll('[data-patch-page]').forEach(el=>el.classList.toggle('active',el.dataset.patchPage===safe));
  }
});

/* 계정 */
const AccountState = {
  current: null
};

const AccountService = Object.freeze({
  normalizeId(value) {
    return String(value || '')
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9_-]/g,'')
      .slice(0,32);
  },
  async request(path, options = {}) {
    const response = await fetch(
      `${DUELS3_CONFIG.accountApiBase}${path}`,
      {
        ...options,
        headers: {
          'Content-Type':'application/json',
          ...(options.headers || {})
        },
        cache:'no-store'
      }
    );

    let body=null;
    try{body=await response.json();}catch{}

    if(!response.ok||body?.ok===false){
      const code=body?.error||'';
      const message=
        body?.message||
        (
          code==='ACCOUNT_NOT_FOUND'
            ?'존재하지 않는 계정입니다.'
            :code==='INVALID_ACCOUNT_DATA'
              ?'계정 데이터 형식이 올바르지 않습니다.'
              :`계정 서버 요청 실패 (${response.status})`
        );

      const error=new Error(message);
      error.status=response.status;
      error.code=code;
      throw error;
    }

    return body||{ok:true};
  }
});

/*
 * 2026-10-31까지의 기존 계정 마이그레이션에만 사용한다.
 * 일반 로그인/회원가입/계정 load/save 기능은 제거했다.
 * AccountService는 공통 Worker 요청과 legacy ID 정규화에만 사용한다.
 */
const LegacyMigrationService=Object.freeze({
  bytesToHex(bytes){
    return Array.from(
      bytes instanceof Uint8Array
        ?bytes
        :new Uint8Array(bytes),
      byte=>
        byte.toString(16)
          .padStart(2,'0')
    ).join('');
  },
  hexToBytes(hex){
    const value=String(hex||'');
    const result=
      new Uint8Array(
        Math.floor(value.length/2)
      );

    for(
      let index=0;
      index<result.length;
      index++
    ){
      result[index]=
        parseInt(
          value.slice(
            index*2,
            index*2+2
          ),
          16
        )||0;
    }

    return result;
  },
  async hashPassword(
    password,
    saltHex,
    iterations=150000
  ){
    if(!crypto?.subtle){
      throw new Error(
        '이 브라우저에서는 안전한 비밀번호 해시를 사용할 수 없습니다.'
      );
    }

    const key=
      await crypto.subtle.importKey(
        'raw',
        new TextEncoder().encode(
          String(password)
        ),
        {name:'PBKDF2'},
        false,
        ['deriveBits']
      );

    const bits=
      await crypto.subtle.deriveBits(
        {
          name:'PBKDF2',
          salt:this.hexToBytes(
            saltHex
          ),
          iterations,
          hash:'SHA-256'
        },
        key,
        256
      );

    return this.bytesToHex(bits);
  },
  decodeBase64UrlText(value){
    let base64=
      String(value||'')
        .replace(/-/g,'+')
        .replace(/_/g,'/');

    while(base64.length%4){
      base64+='=';
    }

    const binary=atob(base64);
    const bytes=
      new Uint8Array(
        binary.length
      );

    for(
      let index=0;
      index<binary.length;
      index++
    ){
      bytes[index]=
        binary.charCodeAt(index);
    }

    return new TextDecoder()
      .decode(bytes);
  },
  challengePayload(challengeToken){
    const encoded=
      String(challengeToken||'')
        .split('.')[0]||'';

    if(!encoded){
      throw new Error(
        '계정 인증 정보를 확인할 수 없습니다.'
      );
    }

    try{
      return JSON.parse(
        this.decodeBase64UrlText(
          encoded
        )
      );
    }catch{
      throw new Error(
        '계정 인증 정보가 올바르지 않습니다.'
      );
    }
  },
  challengeMessage(payload){
    return [
      'duels-auth-v1',
      String(payload?.purpose||''),
      String(payload?.accountId||''),
      String(payload?.nonce||''),
      String(payload?.expiresAt||'')
    ].join('|');
  },
  async createChallengeProof(
    password,
    challenge
  ){
    const hash=
      await this.hashPassword(
        password,
        challenge.salt,
        Number(
          challenge.iterations
        )||150000
      );

    const payload=
      this.challengePayload(
        challenge.challengeToken
      );

    const key=
      await crypto.subtle.importKey(
        'raw',
        this.hexToBytes(hash),
        {
          name:'HMAC',
          hash:'SHA-256'
        },
        false,
        ['sign']
      );

    const signature=
      await crypto.subtle.sign(
        'HMAC',
        key,
        new TextEncoder().encode(
          this.challengeMessage(
            payload
          )
        )
      );

    return this.bytesToHex(
      signature
    );
  },
  async verifyCredentials(
    accountId,
    password
  ){
    const id=
      AccountService.normalizeId(
        accountId
      );

    if(!id||!password){
      throw new Error(
        '아이디와 비밀번호를 입력하세요.'
      );
    }

    const challenge=
      await AccountService.request(
        '/account/migration/challenge',
        {
          method:'POST',
          body:JSON.stringify({
            accountId:id
          })
        }
      );

    if(
      String(
        challenge?.algorithm||
        'PBKDF2-SHA256'
      ).toUpperCase()!==
      'PBKDF2-SHA256'
    ){
      throw new Error(
        '지원하지 않는 기존 비밀번호 형식입니다.'
      );
    }

    const proof=
      await this.createChallengeProof(
        password,
        challenge
      );

    const verified=
      await AccountService.request(
        '/account/migration/verify',
        {
          method:'POST',
          body:JSON.stringify({
            accountId:id,
            challengeToken:
              challenge.challengeToken,
            proof
          })
        }
      );

    return {
      ...verified,
      accountId:id
    };
  },
  async complete(migrationToken){
    const fb=
      globalThis.DuelsFirebase;

    const user=
      fb?.currentUser?.();

    if(!fb||!user){
      throw new Error(
        'Firebase 로그인이 필요합니다.'
      );
    }

    const firebaseIdToken=
      await user.getIdToken(true);

    return AccountService.request(
      '/account/migration/complete',
      {
        method:'POST',
        body:JSON.stringify({
          migrationToken:
            String(
              migrationToken||''
            ),
          firebaseIdToken
        })
      }
    );
  },
  async cancelBinding(
    legacyAccountId
  ){
    const fb=
      globalThis.DuelsFirebase;

    const user=
      fb?.currentUser?.();

    if(!fb||!user){
      throw new Error(
        'Firebase 로그인이 필요합니다.'
      );
    }

    const firebaseIdToken=
      await user.getIdToken(true);

    return AccountService.request(
      '/account/migration/cancel',
      {
        method:'POST',
        body:JSON.stringify({
          legacyAccountId:
            AccountService.normalizeId(
              legacyAccountId
            ),
          firebaseIdToken
        })
      }
    );
  }
});

/* 계정 UI */
const AccountUI = Object.freeze({
  setMessage(text = '', kind = '') {
    const el = document.getElementById('duels3-account-message');
    el.textContent = text;
    el.className = `duels3-account-msg${kind ? ` ${kind}` : ''}`;
  },
  setTab() {
    this.setMessage();
  },
  getGuestIdentity() {
    const key = DUELS3_CONFIG.storageKeys.guestIdentity;
    let id = String(localStorage.getItem(key) || '').trim();
    if (!id) {
      id = (crypto?.randomUUID?.() || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`).toLowerCase();
      localStorage.setItem(key, id);
    }
    return id;
  },
  enter(account, mode = 'account') {
    const savedMainCharacterId=
      (
        typeof account.mainCharacterId==='string'&&
        account.mainCharacterId
      )
        ?account.mainCharacterId
        :(
          typeof account.profile?.mainCharacterId==='string'&&
          account.profile.mainCharacterId
            ?account.profile.mainCharacterId
            :null
        );
    const savedMainCharacterExplicit=
      account.mainCharacterExplicit===true||
      account.profile?.mainCharacterExplicit===true;

    account.mainCharacterId=savedMainCharacterId;
    account.mainCharacterExplicit=savedMainCharacterExplicit;
    account.profile={
      ...(account.profile||{}),
      mainCharacterId:savedMainCharacterId,
      mainCharacterExplicit:savedMainCharacterExplicit
    };
    AccountState.current = account;
    if(globalThis.DebugPanel&&!DebugAccessService.canUse(account))DebugPanel.close();
    if(mode === 'firebase') {
      localStorage.setItem(
        DUELS3_CONFIG.storageKeys.session,
        JSON.stringify({
          mode:'firebase',
          firebaseUid:
            account.firebaseUid||
            account.accountId,
          updatedAt:Date.now()
        })
      );
      if(account.firebaseSyncPending!==true){
        FirebaseAccountCacheService.save(
          account,
          {
            uid:
              account.firebaseUid||
              account.accountId
          }
        );
      }
    } else {
      localStorage.setItem(DUELS3_CONFIG.storageKeys.session, JSON.stringify({mode:'guest',updatedAt:Date.now()}));
    }
    document.getElementById('duels3-account-gate').classList.add('hidden');
    this.updateChip();
    requestAnimationFrame(()=>{
      ProfileSettingsUI.render();
      if(!account.isGuest){
        CharacterRecordService.loadAllRankings().catch(()=>{});
      }
      InviteLinkService.consume();

      const prewarmCharacterSelection=()=>{
        try{
          Training.renderCharacterCards();
        }catch(_){}
      };

      if('requestIdleCallback' in window){
        requestIdleCallback(
          prewarmCharacterSelection,
          {timeout:1200}
        );
      }else{
        setTimeout(
          prewarmCharacterSelection,
          120
        );
      }
    });
  },
  enterGuest() {
    const id = this.getGuestIdentity();
    this.enter({accountId:`guest-${id}`,displayName:'게스트',isGuest:true,characterRecords:{},characterStats:{},mainCharacterId:null,mainCharacterExplicit:false,profile:{mainCharacterId:null,mainCharacterExplicit:false},permissions:{debugTools:false,accountAdmin:false,rankingAdmin:false}}, 'guest');
  },
  logout() {
    const wasFirebase=AccountState.current?.firebaseAccount===true;
    localStorage.removeItem(DUELS3_CONFIG.storageKeys.session);
    DebugPanel?.close?.();
    AccountState.current = null;
    if(wasFirebase){globalThis.DuelsFirebase?.signOutCurrent?.().catch?.(()=>{});}
    document.getElementById('duels3-account-gate').classList.remove('hidden');
    this.setMessage();
    this.updateChip();
  },
  async cancelFirebaseMigration(){
    const account=AccountState.current;
    if(
      !account ||
      account.firebaseAccount!==true ||
      !String(account.legacyAccountId||'').trim()
    ){
      alert('취소할 마이그레이션 계정이 아닙니다.');
      return false;
    }

    const legacyAccountId=String(account.legacyAccountId||'').trim();
    const confirmed=confirm(
      `마이그레이션을 취소할까요?\n\n`+
      `Firebase에 저장된 현재 듀얼즈 계정 데이터는 삭제되고, 기존 GitHub 계정(${legacyAccountId}) 데이터는 그대로 유지됩니다.\n`+
      `다시 마이그레이션하면 GitHub에 남아 있는 기존 계정 데이터를 기준으로 새로 가져옵니다.`
    );
    if(!confirmed)return false;

    const fb=globalThis.DuelsFirebase;
    const user=fb?.currentUser?.();
    if(!fb||!user){
      alert('Firebase 로그인이 필요합니다.');
      return false;
    }
    if(
      account.firebaseUid &&
      String(account.firebaseUid)!==String(user.uid)
    ){
      alert('현재 Google 계정과 마이그레이션된 계정이 일치하지 않습니다.');
      return false;
    }

    try{
      /* 서버의 1:1 바인딩을 먼저 해제한다. 서버 해제가 실패하면 Firebase 문서는 지우지 않는다. */
      const cancelled=
        await LegacyMigrationService.cancelBinding(
          legacyAccountId
        );

      if(cancelled?.accountReset!==true){
        throw new Error(
          '서버에서 계정 초기화가 완료되지 않았습니다.'
        );
      }

      localStorage.removeItem(
        DUELS3_CONFIG.storageKeys.session
      );
      DebugPanel?.close?.();
      AccountState.current=null;
      this.updateChip();

      document
        .getElementById(
          'duels3-account-gate'
        )
        ?.classList.add('hidden');

      FirebaseAccountMigrationUI.open(
        user
      );

      FirebaseAccountMigrationUI.message(
        cancelled?.rankingCleanupPending
          ?`마이그레이션을 취소했습니다. 계정 초기화는 완료됐고 랭킹 정리는 다음 전체 랭킹 재구축 때 반영됩니다. 기존 GitHub 계정 ${legacyAccountId} 데이터는 그대로 유지됩니다.`
          :`마이그레이션을 취소했습니다. 기존 GitHub 계정 ${legacyAccountId} 데이터는 그대로 유지되며, 이 Google 계정은 다시 마이그레이션하거나 새 계정으로 시작할 수 있습니다.`,
        'success'
      );

      return true;
    }catch(error){
      alert(error?.message||'마이그레이션 취소에 실패했습니다.');
      return false;
    }
  },
  setSyncState(text='연결됨',state=''){
    const el=
      document.getElementById(
        'duels3-account-sync-state'
      );
    if(!el)return;
    el.textContent=String(text||'');
    if(state)el.dataset.state=state;
    else delete el.dataset.state;
  },
  updateChip() {
    const chip = document.getElementById('duels3-account-chip');
    const user = AccountState.current;
    chip.replaceChildren();
    chip.style.display = user ? 'flex' : 'none';
    if (!user) { chip.replaceChildren(); return; }

    const strong = document.createElement('strong');
    strong.textContent = user.isGuest ? '게스트' : (user.displayName || user.accountId);
    chip.appendChild(strong);

    const status = document.createElement('span');
    if (user.isGuest) {
      status.dataset.state = 'guest';
      status.textContent = '레코드 저장 안 됨';
    } else {
      status.id = 'duels3-account-sync-state';
      status.textContent =
        user.firebaseSyncPending===true
          ?'동기화 중'
          :'연결됨';
      if(user.firebaseSyncPending===true){
        status.dataset.state='syncing';
      }
    }
    chip.appendChild(status);

    const logout = document.createElement('button');
    logout.type = 'button';
    logout.textContent = user.isGuest ? '로그인' : '로그아웃';
    logout.addEventListener('click', () => this.logout());
    chip.appendChild(logout);
  },
  async restoreSession() {
    let session = null;
    try { session = JSON.parse(localStorage.getItem(DUELS3_CONFIG.storageKeys.session) || 'null'); } catch (_) {}
    if (session?.mode === 'guest') {
      this.enterGuest();
      return true;
    }
    if(session?.mode && session.mode!=='firebase'){
      localStorage.removeItem(DUELS3_CONFIG.storageKeys.session);
    }
    return false;
  }});


/* Firebase 계정 저장소
   - users/{uid}: 표시 이름/메인 캐릭터/마이그레이션 메타데이터 같은 계정 프로필
   - users/{uid}/data/progress: characterRecords / characterStats
   - permissions는 클라이언트 저장 대상에서 제외한다. */
const FirebaseProfilePersistenceService=Object.freeze({
  payload(account=AccountState.current){
    if(!account||account.isGuest||account.firebaseAccount!==true)return null;
    const displayName=String(account.displayName||'플레이어').trim().slice(0,24)||'플레이어';
    const mainCharacterId=(typeof account.mainCharacterId==='string'&&account.mainCharacterId)
      ?account.mainCharacterId
      :null;
    const mainCharacterExplicit=account.mainCharacterExplicit===true;
    return {
      displayName,
      mainCharacterId,
      mainCharacterExplicit,
      profile:{
        ...(account.profile||{}),
        mainCharacterId,
        mainCharacterExplicit
      }
    };
  },
  async save(account=AccountState.current){
    const data=this.payload(account);
    if(!data)return account;
    const fb=globalThis.DuelsFirebase;
    const user=fb?.currentUser?.();
    if(!fb||!user)throw new Error('Firebase 로그인이 필요합니다.');
    if(
      account.firebaseUid&&
      String(account.firebaseUid)!==String(user.uid)
    )throw new Error('현재 Google 계정과 듀얼즈 계정이 일치하지 않습니다.');

    await fb.upsertOwnProfile(data);
    const next={
      ...account,
      ...data,
      firebaseUid:user.uid,
      accountId:user.uid,
      firebaseAccount:true
    };
    FirebaseAccountCacheService.save(
      next,
      user
    );

    if(AccountState.current===account||AccountState.current?.firebaseUid===user.uid){
      AccountState.current=next;
      AccountUI.updateChip();
      const localMember=typeof RoomService!=='undefined'?RoomService.localMember?.():null;
      if(localMember&&typeof PlayerProfileService!=='undefined'){
        localMember.profile=PlayerProfileService.snapshot(next);
      }
    }
    return next;
  }
});

const FirebaseProgressPersistenceService=Object.freeze({
  payload(account=AccountState.current){
    if(!account||account.isGuest||account.firebaseAccount!==true)return null;
    return {
      version:1,
      characterRecords:{...(account.characterRecords||{})},
      characterStats:{...(account.characterStats||{})}
    };
  },
  async save(){
    throw new Error('진행도는 클라이언트에서 직접 저장할 수 없습니다. 온라인 경기 결과를 통해 서버에서만 갱신됩니다.');
  }
});

const FirebaseAccountPersistenceService=Object.freeze({
  async save(account=AccountState.current){
    if(!account||account.isGuest)return account;
    if(account.firebaseAccount!==true){
      throw new Error('기존 듀얼즈 계정의 직접 저장은 종료되었습니다. Google 계정으로 마이그레이션해주세요.');
    }
    const profile=await FirebaseProfilePersistenceService.save(account);
    const next={
      ...profile,
      characterRecords:{...(account.characterRecords||{})},
      characterStats:{...(account.characterStats||{})}
    };
    if(AccountState.current===account||AccountState.current?.firebaseUid===next?.firebaseUid){
      AccountState.current=next;
      AccountUI.updateChip();
    }
    return next;
  }
});

/* Firebase Google 계정 온보딩 / 기존 계정 마이그레이션 */
const FirebaseAccountCacheService=Object.freeze({
  key(uid){
    return (
      DUELS3_CONFIG
        .storageKeys
        .firebaseAccountCachePrefix+
      String(uid||'')
    );
  },
  sanitize(profile,user){
    if(
      !profile ||
      typeof profile!=='object' ||
      profile.duelsAccountReady!==true
    )return null;

    const uid=
      String(
        user?.uid ||
        profile.firebaseUid ||
        profile.accountId ||
        ''
      );

    if(!uid)return null;

    return {
      version:Number(profile.version)||2,
      duelsAccountReady:true,
      firebaseUid:uid,
      accountId:uid,
      legacyAccountId:
        String(profile.legacyAccountId||''),
      displayName:
        String(profile.displayName||'플레이어')
          .trim()
          .slice(0,24)||
        '플레이어',
      mainCharacterId:
        typeof profile.mainCharacterId==='string'
          ?profile.mainCharacterId
          :null,
      mainCharacterExplicit:
        profile.mainCharacterExplicit===true,
      profile:{
        ...(profile.profile||{})
      },
      characterRecords:{
        ...(profile.characterRecords||{})
      },
      characterStats:{
        ...(profile.characterStats||{})
      },
      cachedAt:Date.now()
    };
  },
  save(profile,user){
    const safe=
      this.sanitize(profile,user);

    if(!safe)return false;

    try{
      localStorage.setItem(
        this.key(safe.firebaseUid),
        JSON.stringify(safe)
      );
      return true;
    }catch(_){
      return false;
    }
  },
  load(user){
    const uid=String(user?.uid||'');
    if(!uid)return null;

    try{
      const raw=
        JSON.parse(
          localStorage.getItem(
            this.key(uid)
          )||'null'
        );

      if(
        !raw ||
        raw.duelsAccountReady!==true ||
        String(raw.firebaseUid||raw.accountId||'')!==uid
      )return null;

      /*
       * 캐시는 빠른 화면 복원 전용이다.
       * 관리자 권한은 캐시하지 않고 항상 서버 응답으로만 복구한다.
       */
      return {
        ...raw,
        firebaseUid:uid,
        accountId:uid,
        permissions:{
          debugTools:false,
          accountAdmin:false,
          rankingAdmin:false
        }
      };
    }catch(_){
      return null;
    }
  },
  remove(uid){
    try{
      localStorage.removeItem(
        this.key(uid)
      );
    }catch(_){}
  }
});

const FirebaseAccountMigrationUI={
  legacyAccount:null,
  migrationToken:'',
  firebaseUser:null,
  gate(){return document.getElementById('duels3-migration-gate')},
  message(text='',kind=''){
    const el=document.getElementById('duels3-migration-message');
    if(!el)return;
    el.textContent=String(text||'');
    el.className=`duels3-migration-msg${kind?` ${kind}`:''}`;
  },
  setProgressWarning(show=true){
    document
      .getElementById(
        'duels3-migration-progress-warning'
      )
      ?.classList.toggle(
        'hidden',
        !show
      );
  },
  showForm(show=true){
    document.getElementById('duels3-migration-form')?.classList.toggle('hidden',!show);
    if(show){
      document.getElementById('duels3-new-account-form')?.classList.add('hidden');
      document.getElementById('duels3-migration-id')?.focus();
    }
  },
  showNewAccountForm(show=true){
    document.getElementById('duels3-new-account-form')?.classList.toggle('hidden',!show);
    if(show){
      document.getElementById('duels3-migration-form')?.classList.add('hidden');
      const input=document.getElementById('duels3-new-account-nickname');
      if(input){
        input.value='';
        setTimeout(()=>input.focus(),0);
      }
    }
  },
  resetLegacy(){
    this.legacyAccount=null;
    this.migrationToken='';
    const preview=document.getElementById('duels3-migration-preview');
    preview?.classList.add('hidden');
    if(preview)preview.replaceChildren();
    const confirm=document.getElementById('duels3-migration-confirm');
    if(confirm)confirm.disabled=true;
  },
  open(user){
    this.firebaseUser=user||globalThis.DuelsFirebase?.currentUser?.()||null;
    this.resetLegacy();
    this.showForm(false);
    this.showNewAccountForm(false);
    this.setProgressWarning(false);
    this.message('');
    const account=document.getElementById('duels3-migration-google-account');
    if(account){
      account.textContent=this.firebaseUser
        ?`Google 계정: ${this.firebaseUser.email||this.firebaseUser.displayName||this.firebaseUser.uid}`
        :'';
    }
    this.gate()?.classList.remove('hidden');
  },
  close(){this.gate()?.classList.add('hidden')},
  accountForGame(data,user){
    const profile=(data&&typeof data.profile==='object')?data.profile:{};
    const displayName=String(data?.displayName||user?.displayName||'플레이어').trim().slice(0,24)||'플레이어';
    const mainCharacterId=(typeof data?.mainCharacterId==='string'&&data.mainCharacterId)
      ?data.mainCharacterId
      :(typeof profile.mainCharacterId==='string'&&profile.mainCharacterId?profile.mainCharacterId:null);
    const mainCharacterExplicit=data?.mainCharacterExplicit===true||profile.mainCharacterExplicit===true;
    return {
      version:Number(data?.version)||2,
      accountId:String(user?.uid||data?.accountId||''),
      firebaseUid:String(user?.uid||''),
      legacyAccountId:String(data?.legacyAccountId||''),
      displayName,
      characterRecords:{...(data?.characterRecords||{})},
      characterStats:{...(data?.characterStats||{})},
      mainCharacterId,
      mainCharacterExplicit,
      profile:{...profile,mainCharacterId,mainCharacterExplicit},
      permissions:{
        debugTools:
          data?.permissions?.debugTools===true,
        accountAdmin:
          data?.permissions?.accountAdmin===true,
        rankingAdmin:
          data?.permissions?.rankingAdmin===true
      },
      firebaseAccount:true,
      isGuest:false
    };
  },
  async enterFirebaseProfile(profile,user){
    const account=this.accountForGame(profile,user);
    this.close();
    AccountUI.enter(account,'firebase');
    return account;
  },
  async afterGoogleLogin(resultOrUser){
    const user=
      resultOrUser?.user||
      resultOrUser||
      globalThis.DuelsFirebase
        ?.currentUser?.();

    if(!user){
      throw new Error(
        'Google 로그인 정보를 확인할 수 없습니다.'
      );
    }

    this.firebaseUser=user;

    const cached=
      FirebaseAccountCacheService
        .load(user);

    if(cached){
      /*
       * Firebase Auth가 UID를 확인한 순간 캐시 프로필로 즉시 진입한다.
       * 이 캐시는 화면 복원용일 뿐이며 관리자 권한은 항상 false다.
       * 실제 서버 계정은 아래 백그라운드 요청으로 다시 확인한다.
       */
      const cachedAccount=
        this.accountForGame(
          cached,
          user
        );

      cachedAccount.firebaseSyncPending=true;

      this.close();
      AccountUI.enter(
        cachedAccount,
        'firebase'
      );

      void globalThis.DuelsFirebase
        .loadOwnAccount()
        .then(profile=>{
          if(
            profile?.duelsAccountReady===true
          ){
            FirebaseAccountCacheService
              .save(profile,user);

            const authoritative=
              this.accountForGame(
                profile,
                user
              );

            authoritative.firebaseSyncPending=false;

            if(
              globalThis.DuelsFirebase
                ?.currentUser?.()?.uid===
              user.uid
            ){
              AccountState.current=
                authoritative;

              AccountUI.updateChip();
              ProfileSettingsUI.render();

              const localMember=
                typeof RoomService!=='undefined'
                  ?RoomService.localMember?.()
                  :null;

              if(
                localMember &&
                typeof PlayerProfileService!=='undefined'
              ){
                localMember.profile=
                  PlayerProfileService
                    .snapshot(
                      authoritative
                    );
              }
            }

            return;
          }

          /*
           * 서버에서 계정 준비 상태가 사라졌다면 오래된 캐시를 폐기하고
           * 계정 설정 화면으로 전환한다.
           */
          FirebaseAccountCacheService
            .remove(user.uid);

          if(
            globalThis.DuelsFirebase
              ?.currentUser?.()?.uid===
            user.uid
          ){
            AccountState.current=null;
            AccountUI.updateChip();
            document
              .getElementById(
                'duels3-account-gate'
              )
              ?.classList.add(
                'hidden'
              );
            this.open(user);
          }
        })
        .catch(error=>{
          console.error(
            '[Duels] Firebase 계정 백그라운드 동기화 실패',
            error
          );

          if(
            globalThis.DuelsFirebase
              ?.currentUser?.()?.uid===
            user.uid &&
            AccountState.current
              ?.firebaseUid===
            user.uid
          ){
            AccountState.current.firebaseSyncPending=false;
            AccountUI.updateChip();
            AccountUI.setSyncState(
              '동기화 실패',
              'error'
            );
          }
        });

      return cachedAccount;
    }

    /*
     * 첫 로그인/캐시 없음은 서버에서 계정 존재 여부를 알아야 하므로
     * 기존처럼 1회 기다린다. 성공 후부터는 캐시가 생겨 다음 새로고침이 빨라진다.
     */
    const profile=
      await globalThis.DuelsFirebase
        .loadOwnAccount();

    if(
      profile?.duelsAccountReady===true
    ){
      FirebaseAccountCacheService
        .save(profile,user);

      return this.enterFirebaseProfile(
        profile,
        user
      );
    }

    document
      .getElementById(
        'duels3-account-gate'
      )
      ?.classList.add('hidden');

    this.open(user);
    return null;
  },
  async verifyLegacy(){
    this.resetLegacy();
    const id=document.getElementById('duels3-migration-id')?.value||'';
    const password=document.getElementById('duels3-migration-password')?.value||'';
    if(!id||!password){this.message('기존 아이디와 비밀번호를 입력하세요.','error');return false;}
    this.setProgressWarning(true);
    this.message('기존 계정 인증 정보를 받는 중입니다.');
    try{
      /*
       * Worker는 PBKDF2를 계산하지 않는다.
       * challenge의 salt/iterations로 브라우저가 기존 PBKDF2-SHA256 150000회를 계산하고,
       * 그 결과를 HMAC key로 사용한 proof만 Worker에 보낸다.
       */
      const verified=await LegacyMigrationService.verifyCredentials(id,password);
      this.migrationToken=String(verified?.migrationToken||'');
      if(!this.migrationToken)throw new Error('마이그레이션 인증 토큰을 받지 못했습니다.');

      /*
       * 기존 /account/load API는 폐기되었으므로 인증 응답의 요약 정보만 사용한다.
       * 실제 기존 계정 전체 데이터는 /account/migration/complete에서 서버가 GitHub에서 다시 읽는다.
       */
      const serverAccount=verified?.account||{};
      this.legacyAccount={
        accountId:String(serverAccount.accountId||verified?.accountId||id),
        displayName:String(serverAccount.displayName||''),
        mainCharacterId:typeof serverAccount.mainCharacterId==='string'
          ?serverAccount.mainCharacterId
          :null
      };

      const records=Number.isFinite(Number(serverAccount.characterRecordCount))
        ?Number(serverAccount.characterRecordCount)
        :0;
      const stats=Number.isFinite(Number(serverAccount.characterStatsCount))
        ?Number(serverAccount.characterStatsCount)
        :0;
      const preview=document.getElementById('duels3-migration-preview');
      if(preview){
        preview.replaceChildren();
        const lines=[
          ['기존 아이디',serverAccount.accountId||verified?.accountId||id],
          ['표시 이름',serverAccount.displayName||'-'],
          ['레코드 캐릭터 수',String(records)],
          ['통계 캐릭터 수',String(stats)]
        ];
        for(const [label,value] of lines){
          const row=document.createElement('div');
          const strong=document.createElement('strong');
          strong.textContent=`${label}: `;
          row.append(strong,document.createTextNode(String(value)));
          preview.appendChild(row);
        }
        preview.classList.remove('hidden');
      }
      const confirm=document.getElementById('duels3-migration-confirm');
      if(confirm)confirm.disabled=false;
      const passwordInput=document.getElementById('duels3-migration-password');
      if(passwordInput)passwordInput.value='';
      this.setProgressWarning(false);
      this.message('기존 계정 인증에 성공했습니다. 이전할 Google 계정을 확인한 뒤 진행하세요.','success');
      return true;
    }catch(error){
      const code=String(error?.code||'');
      const friendly=(
        code==='ACCOUNT_ALREADY_MIGRATED'?'이미 마이그레이션된 계정입니다.':
        code==='MIGRATION_PERIOD_ENDED'?'마이그레이션은 10월 31일까지만 지원됩니다.':
        code==='INVALID_LEGACY_CREDENTIALS'?'아이디 또는 비밀번호가 올바르지 않습니다.':
        code==='INVALID_OR_EXPIRED_CHALLENGE'?'인증 시간이 만료되었습니다. 다시 확인해주세요.':
        error?.message||'기존 계정을 확인하지 못했습니다.'
      );
      this.setProgressWarning(false);
      this.message(friendly,'error');
      return false;
    }
  },
  async migrateLegacy(){
    const user=this.firebaseUser||globalThis.DuelsFirebase?.currentUser?.();
    const legacy=this.legacyAccount;
    const migrationToken=String(this.migrationToken||'');
    if(!user||!legacy||!migrationToken){this.message('먼저 기존 계정을 다시 인증하세요.','error');return false;}
    this.setProgressWarning(true);
    const beforeUnloadHandler=event=>{
      event.preventDefault();
      event.returnValue='';
    };
    window.addEventListener(
      'beforeunload',
      beforeUnloadHandler
    );

    this.message('기존 계정과 Google 계정을 1:1로 연결하는 중입니다. 잠시만 기다려주세요.');
    try{
      /*
       * 서버가 migrationToken + Firebase ID Token을 검증한 뒤
       * GitHub의 migration binding 인덱스에 legacyAccountId <-> Firebase UID를 1:1로 고정한다.
       * 서버가 다시 읽어 반환한 GitHub 계정 데이터를 실제 이전 기준으로 사용한다.
       */
      const completed=await LegacyMigrationService.complete(migrationToken);
      const authoritativeLegacy=completed?.account;
      if(!authoritativeLegacy||typeof authoritativeLegacy!=='object'){
        throw new Error('서버에서 이전할 기존 계정 데이터를 받지 못했습니다.');
      }
      if(String(completed?.firebaseUid||'')!==String(user.uid)){
        throw new Error('서버의 Google 계정 연결 정보가 현재 로그인과 일치하지 않습니다.');
      }

      const now=new Date().toISOString();
      const mainCharacterId=(typeof authoritativeLegacy.mainCharacterId==='string'&&authoritativeLegacy.mainCharacterId)
        ?authoritativeLegacy.mainCharacterId
        :(typeof authoritativeLegacy.profile?.mainCharacterId==='string'?authoritativeLegacy.profile.mainCharacterId:null);
      const mainCharacterExplicit=authoritativeLegacy.mainCharacterExplicit===true||authoritativeLegacy.profile?.mainCharacterExplicit===true;
      const migrated={
        version:2,
        duelsAccountReady:true,
        firebaseUid:user.uid,
        legacyAccountId:String(completed?.legacyAccountId||authoritativeLegacy.accountId||legacy.accountId||''),
        displayName:String(authoritativeLegacy.displayName||user.displayName||'플레이어').slice(0,24),
        email:user.email||null,
        createdAt:authoritativeLegacy.createdAt||now,
        updatedAt:now,
        migrated:true,
        migratedAt:completed?.boundAt||now,
        legacyCredentialVerified:true,
        migrationBindingVersion:1,
        mainCharacterId,
        mainCharacterExplicit,
        profile:{...(authoritativeLegacy.profile||{}),mainCharacterId,mainCharacterExplicit},
        characterRecords:{...(authoritativeLegacy.characterRecords||{})},
        characterStats:{...(authoritativeLegacy.characterStats||{})}
      };

      /*
       * 프로필/마이그레이션 메타/진행도는 complete 요청에서 Worker가 서버 권한으로 저장한다.
       * 브라우저는 저장을 반복하지 않고 서버에서 다시 읽은 최종 계정만 사용한다.
       */
      const authoritativeFirebase=await globalThis.DuelsFirebase.loadOwnAccount();
      if(!authoritativeFirebase?.duelsAccountReady){
        throw new Error('서버에 마이그레이션 계정이 생성되지 않았습니다.');
      }
      this.setProgressWarning(false);
      window.removeEventListener(
        'beforeunload',
        beforeUnloadHandler
      );
      this.message('마이그레이션이 완료되었습니다.','success');
      await this.enterFirebaseProfile(authoritativeFirebase,user);
      return true;
    }catch(error){
      const code=String(error?.code||'');
      const friendly=(
        code==='LEGACY_ACCOUNT_ALREADY_BOUND'?'이 기존 계정은 이미 다른 Google 계정에 연결되어 있습니다.':
        code==='FIREBASE_ACCOUNT_ALREADY_BOUND'?'이 Google 계정은 이미 다른 기존 계정에 연결되어 있습니다.':
        code==='INVALID_MIGRATION_TOKEN'?'마이그레이션 인증 시간이 만료되었습니다. 기존 계정을 다시 확인해주세요.':
        code==='INVALID_FIREBASE_TOKEN'?'Google 로그인 인증이 만료되었습니다. 다시 로그인해주세요.':
        error?.message||'마이그레이션 저장에 실패했습니다.'
      );
      this.setProgressWarning(false);
      window.removeEventListener(
        'beforeunload',
        beforeUnloadHandler
      );
      this.message(friendly,'error');
      return false;
    }
  },
  async createNew(){
    const user=this.firebaseUser||globalThis.DuelsFirebase?.currentUser?.();
    if(!user){
      this.message('Google 로그인이 필요합니다.','error');
      return false;
    }

    const input=
      document.getElementById(
        'duels3-new-account-nickname'
      );

    const displayName=
      String(input?.value||'')
        .replace(/[\u0000-\u001f\u007f]/g,'')
        .trim();

    if(!displayName){
      this.message('사용할 닉네임을 입력하세요.','error');
      input?.focus();
      return false;
    }

    if(displayName.length>24){
      this.message('닉네임은 24자 이하로 입력하세요.','error');
      input?.focus();
      return false;
    }

    const confirmed=confirm(
      `닉네임을 "${displayName}"(으)로 설정하고 새 계정을 생성할까요?\n\n`+
      `닉네임은 최초 1회만 설정할 수 있습니다.`
    );
    if(!confirmed)return false;

    const button=
      document.getElementById(
        'duels3-new-account-confirm'
      );
    if(button)button.disabled=true;

    this.message('새 계정을 생성하는 중입니다.');

    try{
      const account=
        await globalThis.DuelsFirebase
          .createOwnAccount({
            displayName
          });

      if(!account?.duelsAccountReady){
        throw new Error(
          '새 계정 생성 결과를 확인할 수 없습니다.'
        );
      }

      return this.enterFirebaseProfile(
        account,
        user
      );
    }catch(error){
      this.message(
        error?.message||
        '새 계정을 만들지 못했습니다.',
        'error'
      );
      return false;
    }finally{
      if(button)button.disabled=false;
    }
  },
  async switchGoogleAccount(){
    const fb=globalThis.DuelsFirebase;
    const button=document.getElementById('duels3-migration-switch-google');

    if(!fb){
      this.message('Firebase 초기화를 기다리는 중입니다.','error');
      return false;
    }

    AuthResolutionUI.setPending(true);
    if(button)button.disabled=true;
    this.message('다른 Google 계정을 선택하는 중입니다.');

    try{
      await fb.signOutCurrent();

      AccountState.current=null;
      localStorage.removeItem(DUELS3_CONFIG.storageKeys.session);
      this.close();
      AccountUI.updateChip();

      const gate=document.getElementById('duels3-account-gate');
      gate?.classList.remove('hidden');
      AccountUI.setMessage('다른 Google 계정으로 로그인하세요.');

      const result=await fb.signInGoogle();

      gate?.classList.add('hidden');
      AccountUI.setMessage('');
      await this.afterGoogleLogin(result);
      AuthResolutionUI.resolve();
      return true;
    }catch(error){
      const code=String(error?.code||'');
      if(
        code==='auth/popup-closed-by-user'||
        code==='auth/cancelled-popup-request'
      ){
        AccountUI.setMessage('Google 계정 선택이 취소되었습니다.');
      }else{
        AccountUI.setMessage(
          error?.message||'Google 계정 변경에 실패했습니다.',
          'error'
        );
      }

      document.getElementById('duels3-account-gate')?.classList.remove('hidden');
      AuthResolutionUI.resolve();
      return false;
    }finally{
      if(button)button.disabled=false;
    }
  },
  bind(){
    document.getElementById('duels3-migration-switch-google')?.addEventListener('click',()=>this.switchGoogleAccount());
    document.getElementById('duels3-migration-existing')?.addEventListener('click',()=>{
      this.resetLegacy();
      this.showNewAccountForm(false);
      this.showForm(true);
      this.message('기존 듀얼즈 계정 정보를 입력하세요.');
    });
    document.getElementById('duels3-migration-new')?.addEventListener('click',()=>{
      this.resetLegacy();
      this.showForm(false);
      this.showNewAccountForm(true);
      this.message('새 계정에서 사용할 닉네임을 입력하세요.');
    });
    document.getElementById('duels3-new-account-confirm')?.addEventListener('click',()=>this.createNew());
    document.getElementById('duels3-new-account-nickname')?.addEventListener('keydown',event=>{
      if(event.key==='Enter')this.createNew();
    });
    document.getElementById('duels3-migration-check')?.addEventListener('click',()=>this.verifyLegacy());
    document.getElementById('duels3-migration-confirm')?.addEventListener('click',()=>this.migrateLegacy());
    document.getElementById('duels3-migration-password')?.addEventListener('keydown',event=>{
      if(event.key==='Enter')this.verifyLegacy();
    });
  }
};



/* 전투 데이터 */
/*
 * 캐릭터 설정 읽기: CHARACTER_DATA만 편집한 뒤 파일을 다시 열면 전투/설명/카드에 함께 반영된다.
 * 시간은 ms, 거리/반지름은 게임 좌표 px, speed는 1프레임 이동량, 비율은 1=100%.
 * damageRatio × stats.baseDamage가 기본 피해. modifier.value는 0.2=20%.
 * characterValue('경로'): 같은 캐릭터 안의 원본을 참조한다. 숫자를 복사하지 않는다.
 * characterValue('경로', 배율): 원본의 배율. characterCount는 배열의 실제 요소 수.
 * 설명의 {v:경로}, {v:경로|seconds}, {v:경로|percent}도 같은 원본을 읽는다.
 * 분류: style/role은 아래 표의 번호, range는 0=실제 평타 최대 사거리로 자동 분류.
 * 별개 기술의 서로 다른 값은 독립 항목이다. 같은 숫자라는 이유로 합치지 않는다.
 * 조회 예: CharacterDataService.numbers('xianelli')는 해석된 모든 숫자와 경로를 반환한다.
 * 공통 엔진의 배열 인덱스·기하 공식·정규화 0/1은 캐릭터 밸런스 값이 아니다.
 */
function characterValue(path,scale=1){
  return scale===1?{$ref:path}:{$ref:path,$scale:scale};
}
function characterCount(path,types=null){
  return types?{$count:path,$types:types}:{$count:path};
}
function characterSum(...values){return {$sum:values};}
function characterProduct(...values){return {$product:values};}
function freezeCharacterData(value){
  if(value&&typeof value==='object'&&!Object.isFrozen(value)){
    for(const child of Object.values(value))freezeCharacterData(child);
    Object.freeze(value);
  }
  return value;
}

