/* 캐릭터 카드 배경 초점 */
const CharacterCardPortraitService=Object.freeze({
  cache:new Map(),
  fallback:Object.freeze({x:50,y:22}),
  directions:Object.freeze([
    Object.freeze({x:-14,y:0}),
    Object.freeze({x:14,y:0}),
    Object.freeze({x:0,y:-12}),
    Object.freeze({x:0,y:12}),
    Object.freeze({x:-10,y:-8}),
    Object.freeze({x:10,y:-8}),
    Object.freeze({x:-10,y:8}),
    Object.freeze({x:10,y:8})
  ]),
  direction(characterId){
    const id=String(characterId||'');
    let hash=2166136261;

    for(let index=0;index<id.length;index++){
      hash^=id.charCodeAt(index);
      hash=Math.imul(hash,16777619);
    }

    return this.directions[Math.abs(hash) % this.directions.length];
  },
  async focus(source,loadedImage=null){
    if(!source)return this.fallback;
    if(this.cache.has(source))return this.cache.get(source);

    const request=this.detect(source,loadedImage).catch(()=>this.fallback);
    this.cache.set(source,request);
    return request;
  },
  async load(source,loadedImage=null){
    if(
      loadedImage?.complete&&
      loadedImage.naturalWidth>0&&
      loadedImage.naturalHeight>0
    ){
      return loadedImage;
    }

    const image=new Image();
    image.crossOrigin='anonymous';
    image.decoding='async';
    image.src=source;
    await image.decode();
    return image;
  },
  silhouetteFocus(image){
    const width=128;
    const height=160;
    const canvas=document.createElement('canvas');
    canvas.width=width;
    canvas.height=height;

    const ctx=canvas.getContext('2d',{
      alpha:true,
      willReadFrequently:true
    });
    if(!ctx)return this.fallback;

    ctx.clearRect(0,0,width,height);

    const scale=Math.min(
      width/image.naturalWidth,
      height/image.naturalHeight
    );
    const drawWidth=image.naturalWidth*scale;
    const drawHeight=image.naturalHeight*scale;
    const drawX=(width-drawWidth)*.5;
    const drawY=(height-drawHeight)*.5;
    ctx.drawImage(image,drawX,drawY,drawWidth,drawHeight);

    const pixels=ctx.getImageData(0,0,width,height).data;
    let minX=width;
    let maxX=-1;
    let minY=height;
    let maxY=-1;
    let opaqueCount=0;

    for(let y=0;y<height;y++){
      for(let x=0;x<width;x++){
        const alpha=pixels[(y*width+x)*4+3];
        if(alpha<24)continue;

        opaqueCount++;
        if(x<minX)minX=x;
        if(x>maxX)maxX=x;
        if(y<minY)minY=y;
        if(y>maxY)maxY=y;
      }
    }

    if(
      opaqueCount<80||
      maxX<minX||
      maxY<minY
    ){
      return this.fallback;
    }

    const bodyWidth=maxX-minX+1;
    const bodyHeight=maxY-minY+1;

    const headBottom=Math.min(
      maxY,
      minY+Math.max(16,Math.round(bodyHeight*.38))
    );

    let weight=0;
    let weightedX=0;
    let weightedY=0;

    for(let y=minY;y<=headBottom;y++){
      const vertical=
        1.25-
        .45*((y-minY)/Math.max(1,headBottom-minY));

      for(let x=minX;x<=maxX;x++){
        const alpha=pixels[(y*width+x)*4+3]/255;
        if(alpha<.10)continue;

        const centerBias=
          .72+
          .28*Math.max(
            0,
            1-Math.abs(
              (x-(minX+maxX)*.5)/
              Math.max(1,bodyWidth*.5)
            )
          );

        const w=alpha*vertical*centerBias;
        weight+=w;
        weightedX+=x*w;
        weightedY+=y*w;
      }
    }

    if(weight<=0)return this.fallback;

    const headX=weightedX/weight;
    const headY=weightedY/weight;

    return {
      x:Math.max(16,Math.min(84,headX/width*100)),
      y:Math.max(7,Math.min(40,headY/height*100-2))
    };
  },
  async detect(source,loadedImage=null){
    const image=await this.load(source,loadedImage);
    return this.silhouetteFocus(image);
  },
  sync(root=document){
    if(!root)return;

    if(!DisplaySettings.state.characterCardIllustrations){
      for(const background of root.querySelectorAll('.char-card-portrait-bg')){
        background.remove();
      }
      return;
    }

    for(const card of root.querySelectorAll('.char-card[data-id]')){
      if(card.querySelector(':scope > .char-card-portrait-bg'))continue;
      const character=CharacterCardDataService.get(card.dataset.id);
      if(character)this.attach(card,character);
    }
  },
  animateEntrance(root=document){
    if(
      !root||
      !DisplaySettings.state.characterCardIllustrations
    )return false;

    const cards=root.matches?.('.char-card[data-id]')
      ?[root]
      :[
        ...root.querySelectorAll(
          '.char-card[data-id]'
        )
      ];

    let animated=0;

    for(const [index,card] of cards.entries()){
      const background=card.querySelector(
        ':scope > .char-card-portrait-bg.loaded'
      );
      if(!background)continue;

      const direction=this.direction(card.dataset.id);

      for(const animation of background.getAnimations?.()||[]){
        if(animation.id==='duels-portrait-enter'){
          animation.cancel();
        }
      }

      const animation=background.animate(
        [
          {
            opacity:0,
            transform:
              `translate(${direction.x}%, ${direction.y}%) scale(1.075)`
          },
          {
            opacity:.75,
            transform:
              'translate(0, 0) scale(1.055)'
          }
        ],
        {
          duration:420,
          delay:index*10,
          easing:'cubic-bezier(.2,.76,.24,1)',
          fill:'both'
        }
      );

      animation.id='duels-portrait-enter';
      animation.addEventListener(
        'finish',
        ()=>animation.cancel(),
        {once:true}
      );

      animated++;
    }

    return animated>0;
  },
  attach(card,character,onReady=null){
    if(
      !card||
      !character||
      !DisplaySettings.state.characterCardIllustrations||
      card.querySelector(':scope > .char-card-portrait-bg')
    )return null;

    const source=ProfileCharacterImageService.source(character.id);
    if(!source)return;

    const direction=this.direction(character.id);
    const background=document.createElement('div');
    background.className='char-card-portrait-bg';
    background.style.backgroundImage=`url("${source}")`;
    background.style.setProperty('--portrait-focus-x','50%');
    background.style.setProperty('--portrait-focus-y','22%');
    background.style.setProperty('--portrait-enter-x',`${direction.x}%`);
    background.style.setProperty('--portrait-enter-y',`${direction.y}%`);

    const image=new Image();
    image.crossOrigin='anonymous';
    image.decoding='async';
    image.src=source;

    image.addEventListener('load',()=>{
      if(!background.isConnected)return;

      this.focus(source,image).then(focus=>{
        if(!background.isConnected)return;
        const focusX=Math.max(22,Math.min(78,focus.x));
        const focusY=Math.max(10,Math.min(30,focus.y-1));
        background.style.setProperty('--portrait-focus-x',`${focusX}%`);
        background.style.setProperty('--portrait-focus-y',`${focusY}%`);
      });

      requestAnimationFrame(()=>{
        if(!background.isConnected)return;
        background.classList.add('loaded');
        onReady?.(background,card);
      });
    },{once:true});

    image.addEventListener('error',()=>{
      background.remove();
    },{once:true});

    card.prepend(background);
    return background;
  }
});

/* 프로필/레코드 캐릭터 목록은 실제 전투 캐릭터 데이터만 사용한다. */
const ProfileCharacterService=Object.freeze({
  catalog:Object.freeze(
    Object.values(GAME_DATA.characters)
  ),
  all(){
    return this.catalog;
  },
  get(characterId){
    return GAME_DATA.characters[characterId]||null;
  },
  has(characterId){
    return !!GAME_DATA.characters[characterId];
  }
});

/* 캐릭터 카드 카탈로그 */
const CharacterCardDataService=Object.freeze({
  cache:new Map(),
  list:[],
  all(){
    if(this.list.length)return this.list;

    for(const character of ProfileCharacterService.all()){
      const card=this.get(character.id);
      if(card)this.list.push(card);
    }

    return this.list;
  },
  get(characterId){
    if(this.cache.has(characterId)){
      return this.cache.get(characterId);
    }

    const combat=
      ProfileCharacterService.get(characterId);
    if(!combat)return null;

    const card=Object.freeze({
      ...combat,
      maxHealth:combat.maxHealth,
      moveLabel:combat.moveLabel,
      styleLabel:
        TagService.characterStyleLabel(combat),
      desc:combat.desc||'',
      combat
    });

    this.cache.set(characterId,card);
    return card;
  }
});

/* 선택/라운드 준비가 공유하는 단일 캐릭터 카드 뷰 */
const CharacterCardViewService=Object.freeze({
  create(characterLike,{
    account=AccountState.current,
    selected=false,
    cursor='pointer'
  }={}){
    const combat=characterLike?.combat||characterLike;
    if(!combat?.id)return null;
    const characterId=combat.id;
    const card=document.createElement('div');
    card.className=`char-card${selected?' sel':''}`;
    card.dataset.id=characterId;
    card.dataset.charTooltip='true';
    if(cursor)card.style.cursor=cursor;

    const tooltip=document.createElement('div');
    tooltip.className='char-tooltip';
    tooltip.innerHTML=CharacterDescriptionService.html(
      combat,
      {
        recordPoints:CharacterRecordService.points(
          characterId,
          account
        )
      }
    );

    const icon=document.createElement('div');
    icon.className='char-icon';
    CharacterCardColorService.applyIcon(icon,combat);

    const name=document.createElement('div');
    name.className='char-name';
    CharacterCardColorService.applyName(name,combat);
    name.textContent=combat.name;

    const stats=document.createElement('div');
    stats.className='char-stats';
    stats.innerHTML=CharacterCardStatsService.html(
      CharacterCardStatsService.rows(combat)
    );

    card.append(tooltip,icon,name,stats);
    CharacterRecordService.applyCardStyle?.(
      card,
      characterId,
      account
    );
    CharacterCardInteractionService.bind(
      card,
      {account}
    );
    CharacterRecordService.resetCardView(card);
    CharacterCardPortraitService.attach(card,combat);
    return card;
  }
});

const CharacterSortService=Object.freeze({
  storageKey:'duels3.characterSortMode',
  modes:Object.freeze([
    'release',
    'record-desc',
    'record-asc',
    'difficulty-desc',
    'difficulty-asc',
    'color-rainbow',
    'combat-style',
    'range-desc',
    'range-asc',
    'role'
  ]),
  distanceTags:Object.freeze(CHARACTER_RULES.ranges.map(item=>item.tag)),
  normalizeMode(mode){
    return this.modes.includes(mode)
      ?mode
      :'release';
  },
  loadMode(){
    try{
      return this.normalizeMode(
        String(
          localStorage.getItem(this.storageKey)||''
        )
      );
    }catch(_){
      return 'release';
    }
  },
  setMode(mode){
    const selected=this.normalizeMode(mode);
    try{
      localStorage.setItem(
        this.storageKey,
        selected
      );
    }catch(_){}
    return selected;
  },
  releaseOrder(){
    const map=new Map();
    CharacterCardDataService.all().forEach(
      (character,index)=>map.set(character.id,index)
    );
    return map;
  },
  releaseIndex(character,order){
    return order.get(character?.id)??Number.MAX_SAFE_INTEGER;
  },
  attackById(combat,attackId){
    if(!combat?.attacks||!attackId)return null;
    return Object.values(combat.attacks).find(
      attack=>String(attack?.id||'')===String(attackId)
    )||null;
  },
  initialSource(combat){
    const source={character:combat,actionState:new Map(),alive:true,
      maxHealth:combat.maxHealth||1,maxStamina:combat.maxStamina||1};
    // Passive initialization uses the same progress store as actual gameplay.
    for(const module of combat.passives||[]){
      if(module.type!=='state.progress-rate')continue;
      const mode=module.whenMode;
      if(mode&&ModeStateService.current(source,mode.stateKey,mode.initial)!==mode.value)continue;
      ProgressStateService.ensure(source,module);
    }
    return source;
  },
  initialConditionsMatch(conditions,source){
    return (conditions||[]).every(condition=>
      !String(condition.type||'').startsWith('state.')||
      TriggerConditionService.matches(condition,{source})
    );
  },
  lmbAttackEntries(combat,source=this.initialSource(combat)){
    const ability=combat?.abilities?.lmb;
    if(!ability)return [];
    const entries=[];
    const push=id=>{if(id&&!entries.includes(id))entries.push(id);};
    const candidateConditions=candidate=>Array.isArray(candidate.conditions)
      ?candidate.conditions:candidate.stateKey
        ?[{type:candidate.phase?'state.phase':'state.exists',stateKey:candidate.stateKey,phase:candidate.phase}]:[];
    let inputIds=[ability.attackId];
    for(const candidate of ability.inputAttackAlternates||[]){
      const conditions=candidateConditions(candidate);
      if(candidate.rangeAvailableInitially===true){inputIds.push(candidate.attackId);continue;}
      if(!this.initialConditionsMatch(conditions,source))continue;
      if(conditions.every(c=>String(c.type).startsWith('state.'))){inputIds=[candidate.attackId];break;}
      inputIds.push(candidate.attackId);
    }
    const visit=modules=>{
      for(const module of modules||[]){
        if(!this.initialConditionsMatch(module.conditions,source))continue;
        if(module.requireAttackId&&!entries.includes(module.requireAttackId))continue;
        if(module.type==='action.attack'){
          let defaults=module.attackId?[module.attackId]:inputIds;
          for(const candidate of [...(module.alternates||[]),...(module.alternateWhen?[module.alternateWhen]:[])]){
            const conditions=candidateConditions(candidate);
            if(candidate.rangeAvailableInitially===true){push(candidate.attackId);continue;}
            if(!this.initialConditionsMatch(conditions,source))continue;
            // Position/aim choices remain possible in the initial mode. A
            // matching state-only alternative replaces the fallback attack.
            if(conditions.length&&conditions.every(c=>String(c.type).startsWith('state.'))){defaults=[candidate.attackId];break;}
            push(candidate.attackId);
          }
          for(const id of defaults)push(id);
        }else if(module.type==='action.trigger-attack')push(module.attackId||ability.attackId);
        if(Array.isArray(module.modules))visit(module.modules);
      }
    };
    visit(ability.trigger?.modules);
    if(!entries.length)for(const id of inputIds)push(id);
    return entries.map(attackId=>({attackId}));
  },
  primaryAttacks(character,source=null){
    const combat=character?.combat||character;
    if(!combat?.attacks)return [];
    source=source||this.initialSource(combat);
    return this.lmbAttackEntries(combat,source)
      .map(entry=>this.attackById(combat,entry.attackId))
      .filter(attack=>attack?.tags?.includes?.('평타')&&
        !attack.tags.includes('반격')&&!attack.tags.includes('스킬')&&!attack.tags.includes('소환수'));
  },
  rangeValue(value){
    const number=Number(value);
    if(number===Infinity)return Infinity;
    return Number.isFinite(number)
      ?Math.max(0,number)
      :0;
  },
  enemyRangeModule(module){
    const relations=module?.targetRelations;
    return !Array.isArray(relations)||!relations.length||relations.includes('enemy');
  },
  geometryRange(module,attack){
    const range=this.rangeValue(module.range??attack.range);
    let center=this.rangeValue(module.centerDistance);
    if(module.centerMode==='live-aim-point')center=this.rangeValue(module.centerMaxRange??attack.range);
    if(Number(module.repeatCount)>1&&module.repeatCenterDistanceStart!==undefined){
      center=Math.max(center,this.rangeValue(module.repeatCenterDistanceStart)+
        (Number(module.repeatCount)-1)*this.rangeValue(module.repeatCenterDistanceStep));
    }
    return center+range*(module.shape==='rect'&&module.rectCenterMode==='center'?.5:1);
  },
  rangeVariants(attack,source=null){
    if(source&&attack.progressScale?.rangeBasis==='initial'){
      attack={...ProgressScaledAttackService.resolve(source,attack),progressScale:null};
    }
    const variants=[attack];
    for(const scale of [attack.charge,attack.progressScale]){
      if(!scale)continue;
      for(const endpoint of ['from','to']){
        const range=scale.range?.[endpoint]??attack.range;
        const modules=(attack.modules||[]).map(module=>{
          const copy={...module};
          if(scale.range&&module.range===attack.range)copy.range=range;
          for(const value of scale.moduleValues||[]){
            if(value.type===module.type&&value[endpoint]!==undefined)copy[value.property]=value[endpoint];
          }
          return copy;
        });
        variants.push({...attack,range,modules,damageRatio:scale.damageRatio?.[endpoint]??attack.damageRatio});
      }
      if(scale.fullSpec)variants.push({...attack,...scale.fullSpec,charge:null,progressScale:null});
    }
    return variants;
  },
  attackMaxRange(attack,combat=null,visited=new Set(),source=null){
    if(!attack||visited.has(attack))return 0;
    const nextVisited=new Set(visited);nextVisited.add(attack);
    let maximum=0;
    const linkedRange=id=>this.attackMaxRange(this.attackById(combat,id),combat,nextVisited,source);
    for(const variant of this.rangeVariants(attack,source)){
      const modules=variant.modules||[];
      const projectile=modules.find(m=>['delivery.projectile','delivery.range-projectile'].includes(m.type));
      let travel=this.rangeValue(variant.range);
      if(projectile?.targetPoint===true&&projectile.targetPointClampToAttackRange===false)travel=Infinity;
      const damage=Number(variant.damageRatio)>0&&variant.effectsOnly!==true;
      for(const module of modules){
        if(!this.enemyRangeModule(module))continue;
        const type=String(module.type||'');
        if(type==='delivery.area'&&damage)maximum=Math.max(maximum,this.geometryRange(module,variant));
        if(type==='delivery.hitscan'&&damage)maximum=Math.max(maximum,this.rangeValue(module.range??variant.range));
        if(['delivery.projectile','delivery.range-projectile'].includes(type)&&damage&&module.damageOnTravel!==false){
          maximum=Math.max(maximum,module.orbit
            ?this.rangeValue(module.orbit.maxRadius)+this.rangeValue(module.radius):travel);
        }
        if(type==='formation.manifest'&&damage)maximum=Math.max(maximum,travel);
        if(type==='effect.spawn'&&module.damage){
          const effectDamage=module.damage;
          if(effectDamage.module)maximum=Math.max(maximum,this.geometryRange(effectDamage.module,variant));
          else if(effectDamage.requireMovementExecution===true||effectDamage.hitMode==='body-contact'){
            const movement=modules.find(m=>m.type==='movement.move');
            const distance=movement?this.rangeValue(movement.distance??(Number(movement.speed)||0)*(Number(movement.duration)||0)/1000):0;
            maximum=Math.max(maximum,distance+this.rangeValue(effectDamage.contactRadius));
          }else maximum=Math.max(maximum,this.rangeValue(module.range??variant.range));
        }
        if(type==='projectile.impact'&&projectile){
          const ids=[...(module.attackIds||[])];
          for(const values of Object.values(module.reasonAttackIds||{}))ids.push(...values);
          for(const id of ids){const extent=linkedRange(id);if(extent>0)maximum=Math.max(maximum,travel+extent);}
          const field=module.field;
          if(field?.damageOnTrigger!==false&&field?.attackId&&Number(this.attackById(combat,field.attackId)?.damageRatio)>0&&this.enemyRangeModule(field)){
            maximum=Math.max(maximum,field.anchorMode==='projectile-path'?travel:travel+this.geometryRange(field,variant));
          }
        }
        if(type==='projectile.wall-relay'&&projectile){const extent=linkedRange(module.attackId);if(extent>0)maximum=Math.max(maximum,travel+extent);}
        if(type==='state.window'){
          for(const id of Object.values(module.resolveAttackIds||{}))maximum=Math.max(maximum,linkedRange(id));
        }
        if(type==='field.area'&&module.damageOnTrigger!==false&&module.attackId&&Number(this.attackById(combat,module.attackId)?.damageRatio)>0){
          const origin=module.anchorMode==='attack-end'?travel:0;
          maximum=Math.max(maximum,origin+this.geometryRange(module,variant));
        }
        if(type==='movement.move'&&module.damage){
          maximum=Math.max(maximum,this.rangeValue(module.distance)+this.rangeValue(module.damage.contactRadius));
        }
      }
    }
    return maximum;
  },
  basicRange(character){
    const combat=character?.combat||character;
    const source=this.initialSource(combat);
    let maximum=0;
    for(const attack of this.primaryAttacks(character,source)){
      maximum=Math.max(
        maximum,
        this.attackMaxRange(attack,combat,new Set(),source)
      );
    }
    return maximum;
  },
  distanceTag(character){
    const range=this.basicRange(character);
    return CHARACTER_RULES.ranges.find(item=>range<=item.maxInclusive)?.tag||'';
  },
  styleLabel(character){
    return [this.combatStyle(character),this.distanceTag(character),this.role(character)].filter(Boolean).join(' ');
  },
  role(character){
    const combat=character?.combat||character;
    return CHARACTER_RULES.roles[combat?.classification?.role]||'';
  },
  combatStyle(character){
    const combat=character?.combat||character;
    return CHARACTER_RULES.styles[combat?.classification?.style]||'';
  },
  colorRgb(character){
    const combat=character?.combat||character;
    const raw=String(combat?.color||'').trim();

    if(/^#[0-9a-f]{3}$/i.test(raw)){
      return {
        r:parseInt(raw[1]+raw[1],16),
        g:parseInt(raw[2]+raw[2],16),
        b:parseInt(raw[3]+raw[3],16)
      };
    }

    if(/^#[0-9a-f]{6}$/i.test(raw)){
      return {
        r:parseInt(raw.slice(1,3),16),
        g:parseInt(raw.slice(3,5),16),
        b:parseInt(raw.slice(5,7),16)
      };
    }

    const rgb=raw.match(
      /^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/i
    );
    if(rgb){
      return {
        r:Math.max(0,Math.min(255,Number(rgb[1])||0)),
        g:Math.max(0,Math.min(255,Number(rgb[2])||0)),
        b:Math.max(0,Math.min(255,Number(rgb[3])||0))
      };
    }

    return null;
  },
  colorOklch(character){
    const rgb=this.colorRgb(character);
    if(!rgb){
      return {l:0,c:0,h:0};
    }

    const srgbToLinear=value=>{
      const normalized=
        Math.max(
          0,
          Math.min(
            1,
            Number(value)/255
          )
        );
      return normalized<=.04045
        ?normalized/12.92
        :Math.pow(
          (normalized+.055)/1.055,
          2.4
        );
    };

    const r=srgbToLinear(rgb.r);
    const g=srgbToLinear(rgb.g);
    const b=srgbToLinear(rgb.b);

    const l=
      .4122214708*r+
      .5363325363*g+
      .0514459929*b;
    const m=
      .2119034982*r+
      .6806995451*g+
      .1073969566*b;
    const s=
      .0883024619*r+
      .2817188376*g+
      .6299787005*b;

    const lRoot=Math.cbrt(l);
    const mRoot=Math.cbrt(m);
    const sRoot=Math.cbrt(s);

    const lightness=
      .2104542553*lRoot+
      .793617785*mRoot-
      .0040720468*sRoot;
    const a=
      1.9779984951*lRoot-
      2.428592205*mRoot+
      .4505937099*sRoot;
    const bAxis=
      .0259040371*lRoot+
      .7827717662*mRoot-
      .808675766*sRoot;

    const chroma=Math.hypot(a,bAxis);
    let hue=
      Math.atan2(bAxis,a)*
      180/Math.PI;
    if(hue<0)hue+=360;

    return {
      l:lightness,
      c:chroma,
      h:hue
    };
  },
  groupOrder(characters,resolver){
    const order=new Map();
    let index=0;
    for(const character of characters){
      const key=resolver(character)||'';
      if(!order.has(key)){
        order.set(key,index++);
      }
    }
    return order;
  },
  sorted(mode,account=AccountState.current){
    const source=[
      ...CharacterCardDataService.all()
    ];
    const selected=
      this.modes.includes(mode)
        ?mode
        :'release';
    const release=this.releaseOrder();
    const releaseTie=(a,b)=>
      this.releaseIndex(a,release)-
      this.releaseIndex(b,release);

    if(selected==='release')return source;

    if(selected==='record-desc'){
      return source.sort((a,b)=>
        CharacterRecordService.points(b.id,account)-
        CharacterRecordService.points(a.id,account)||
        releaseTie(a,b)
      );
    }

    if(selected==='record-asc'){
      return source.sort((a,b)=>
        CharacterRecordService.points(a.id,account)-
        CharacterRecordService.points(b.id,account)||
        releaseTie(a,b)
      );
    }

    if(selected==='difficulty-desc'){
      return source.sort((a,b)=>
        CharacterDifficultyService.level(b)-
        CharacterDifficultyService.level(a)||
        releaseTie(a,b)
      );
    }

    if(selected==='difficulty-asc'){
      return source.sort((a,b)=>
        CharacterDifficultyService.level(a)-
        CharacterDifficultyService.level(b)||
        releaseTie(a,b)
      );
    }

    if(selected==='color-rainbow'){
      return source.sort((a,b)=>{
        const aColor=this.colorOklch(a);
        const bColor=this.colorOklch(b);

        /*
          OKLCH hue는 원형이므로 분홍 계열을 시작점으로 한 번만 회전한다.
          350° 부근을 절단점으로 잡으면 분홍→빨강→...→보라→자주 순으로
          이어지고 끝에서 다시 분홍 그룹을 만들지 않는다.
        */
        const hueStart=350;
        const aHue=
          (aColor.h-hueStart+360)%360;
        const bHue=
          (bColor.h-hueStart+360)%360;
        const hueDifference=aHue-bHue;
        if(Math.abs(hueDifference)>.0001){
          return hueDifference;
        }

        const chromaDifference=
          bColor.c-aColor.c;
        if(Math.abs(chromaDifference)>.0001){
          return chromaDifference;
        }

        const lightnessDifference=
          bColor.l-aColor.l;
        if(Math.abs(lightnessDifference)>.0001){
          return lightnessDifference;
        }

        return releaseTie(a,b);
      });
    }

    if(selected==='range-desc'){
      return source.sort((a,b)=>{
        const aRange=this.basicRange(a);
        const bRange=this.basicRange(b);
        return aRange===bRange
          ?releaseTie(a,b)
          :bRange-aRange;
      });
    }

    if(selected==='range-asc'){
      return source.sort((a,b)=>{
        const aRange=this.basicRange(a);
        const bRange=this.basicRange(b);
        return aRange===bRange
          ?releaseTie(a,b)
          :aRange-bRange;
      });
    }

    if(selected==='combat-style'){
      const groups=this.groupOrder(
        source,
        character=>this.combatStyle(character)
      );
      return source.sort((a,b)=>{
        const aStyle=this.combatStyle(a);
        const bStyle=this.combatStyle(b);
        return (
          (groups.get(aStyle)??999)-
          (groups.get(bStyle)??999)||
          releaseTie(a,b)
        );
      });
    }

    if(selected==='role'){
      const roleOrder=new Map(
        (GAME_DATA.characterRoleTags||[])
          .map((role,index)=>[role,index])
      );
      return source.sort((a,b)=>{
        const aRole=this.role(a);
        const bRole=this.role(b);
        return (
          (roleOrder.get(aRole)??999)-
          (roleOrder.get(bRole)??999)||
          releaseTie(a,b)
        );
      });
    }

    return source;
  }
});

/* 캐릭터 프로필 시각화 */
const CharacterPortraitService=Object.freeze({
  imageSource(character){
    if(!character)return '';

    const explicitKeys=[
      'profileImage',
      'portrait',
      'portraitUrl',
      'image',
      'imageUrl',
      'icon',
      'iconUrl',
      'sprite'
    ];

    for(const key of explicitKeys){
      const value=character[key];
      if(typeof value==='string'&&value.trim())return value.trim();
    }

    if(ProfileCharacterService.has(character.id)){
      return ProfileCharacterImageService.source(character.id);
    }

    return '';
  },
  create(character,className=''){
    const node=document.createElement('div');
    node.className=className;

    const color=character?.color||'#8292a0';
    node.style.setProperty('--profile-color',color);

    const source=this.imageSource(character);

    if(source){
      const image=document.createElement('img');
      image.src=source;
      image.alt='';
      image.draggable=false;
      image.loading='eager';

      image.addEventListener('load',()=>{
        node.classList.add('has-image');
        node.classList.remove('color-only');
        node.style.background='#091018';
      },{once:true});

      image.addEventListener('error',()=>{
        image.remove();
        node.classList.remove('has-image');
        node.classList.add('color-only');
        node.style.background=color;
      },{once:true});

      node.style.background='#091018';
      node.appendChild(image);
    }else{
      node.classList.add('color-only');
      node.style.background=color;
    }

    return node;
  }
});

/* 캐릭터 카드 통계 / 랭킹 */
let characterCardTopPlayerBaseline=null;
const CharacterCardLayoutService=Object.freeze({
  measureBaseline(root=document){
    let best=null;

    for(const card of root.querySelectorAll('.char-card')){
      if(
        card.classList.contains('char-card-compact-lines')
      )continue;

      const badge=
        card.querySelector(
          ':scope > .char-top-player-badge'
        );
      if(!badge||badge.hidden)continue;

      const top=
        badge.offsetTop;
      if(!Number.isFinite(Number(top)))continue;

      if(best===null||top>best){
        best=top;
      }
    }

    if(best!==null){
      characterCardTopPlayerBaseline=best;
    }

    return characterCardTopPlayerBaseline;
  },
  sync(card){
    if(!card?.classList)return false;

    card.classList.remove(
      'char-card-compact-lines'
    );
    card.style.removeProperty(
      '--top-player-shift'
    );

    const badge=
      card.querySelector(
        ':scope > .char-top-player-badge'
      );
    if(!badge||badge.hidden)return false;

    const stats=
      card.querySelector(
        ':scope > .char-stats'
      );
    if(!stats)return false;

    let wrapped=false;
    for(const row of stats.children){
      const style=getComputedStyle(row);
      const lineHeight=
        Number.parseFloat(style.lineHeight)||
        Number.parseFloat(style.fontSize)*1.32||
        15;
      if(
        row.getBoundingClientRect().height>
        lineHeight*1.55
      ){
        wrapped=true;
        break;
      }
    }

    if(wrapped){
      card.classList.add(
        'char-card-compact-lines'
      );
    }

    requestAnimationFrame(()=>{
      const baseline=
        this.measureBaseline(
          card.closest(
            '#scr-select,#scr-between'
          )||document
        );

      if(
        wrapped&&
        baseline!==null
      ){
        const current=
          badge.offsetTop;
        const delta=
          Math.round(
            Number(baseline)-
            Number(current)
          );

        card.style.setProperty(
          '--top-player-shift',
          `${delta}px`
        );
      }
    });

    return wrapped;
  },
  schedule(card){
    if(!card)return false;
    requestAnimationFrame(()=>
      this.sync(card)
    );
    return true;
  }
});

const CharacterTitleService=Object.freeze({
  titles:Object.freeze(Object.fromEntries(
    Object.values(GAME_DATA.characters).map(character=>[character.id,character.title])
  )),

  get(characterId){
    return (
      this.titles[
        String(characterId||'')
      ]||
      '칭호 미지정'
    );
  },

  attach(card,characterId,points=0){
    if(!card)return false;

    const apply=()=>{
      if(
        !card?.isConnected&&
        !card.querySelector?.('.char-name')
      )return false;

      const name=
        card.querySelector(
          ':scope > .char-name'
        )||
        card.querySelector('.char-name');
      if(!name)return false;

      const tier=
        CharacterRecordService.tier(
          points
        );
      const visible=
        tier.id==='master'&&
        Number(tier.masterLevel)>=5;

      let title=
        name.querySelector(
          ':scope > .char-title'
        )||
        card.querySelector(
          ':scope > .char-title'
        );

      if(!visible){
        title?.remove();
        CharacterCardLayoutService.schedule(
          card
        );
        return false;
      }

      if(!title){
        title=document.createElement('span');
        title.className='char-title';
      }

      if(title.parentElement!==name){
        title.remove();
        name.appendChild(title);
      }

      title.textContent=
        this.get(characterId);
      CharacterCardLayoutService.schedule(
        card
      );
      return true;
    };

    if(apply())return true;

    queueMicrotask(()=>{
      apply();
    });
    return false;
  }
});

const CharacterRecordService=Object.freeze({
  rankingCache:new Map(),
  rankingCacheMs:30000,
  allRankingState:{characters:{},loadedAt:0,promise:null},
  clearRankingCache(){
    this.rankingCache.clear();
    this.allRankingState.characters={};
    this.allRankingState.loadedAt=0;
    this.allRankingState.promise=null;
    return true;
  },
  masteryTiers:Object.freeze([
    Object.freeze({id:'master',name:'마스터 I',min:12000,gradient:'linear-gradient(135deg,#ffe34f,#ff9d38,#a86cff,#6f3dd6)',glow:'rgba(205,120,255,.72)',text:'#f0c3ff'}),
    Object.freeze({id:'platinum',name:'플레티넘',min:8000,gradient:'linear-gradient(135deg,#76d8ff,#9eeeff,#aaf2c1,#66d991)',glow:'rgba(105,225,205,.72)',text:'#8fe8cf'}),
    Object.freeze({id:'diamond',name:'다이아',min:5000,gradient:'linear-gradient(135deg,#1769d2,#4aa8ff,#9de8ff,#2476df)',glow:'rgba(45,145,255,.72)',text:'#68baff'}),
    Object.freeze({id:'gold',name:'골드',min:3000,gradient:'linear-gradient(135deg,#9b6500,#ffe066,#c99200)',glow:'rgba(255,205,45,.58)',text:'#ffd84c'}),
    Object.freeze({id:'silver',name:'실버',min:1500,gradient:'linear-gradient(135deg,#7d8792,#eef4fa,#89939d)',glow:'rgba(210,225,240,.52)',text:'#dce8f2'}),
    Object.freeze({id:'bronze',name:'브론즈',min:500,gradient:'linear-gradient(135deg,#5f2f18,#a95625,#d07a3b,#713419)',glow:'rgba(184,86,37,.58)',text:'#d98248'}),
    Object.freeze({id:'none',name:'없음',min:0,gradient:'linear-gradient(135deg,#27313d,#3a4654)',glow:'rgba(80,100,120,.12)',text:'#7e8995'})
  ]),
  normalizeAllRankings(payload){
    const source=
      payload?.characters&&
      typeof payload.characters==='object'&&
      !Array.isArray(payload.characters)
        ?payload.characters
        :{};

    const characters={};

    for(const [characterId,entries] of Object.entries(source)){
      if(!ProfileCharacterService.has(characterId))continue;
      characters[characterId]=this.normalizeRanking(entries,characterId);
    }

    return characters;
  },
  refreshTopPlayerBadges(root=document){
    const account=AccountState.current;
    const accountId=String(
      account?.firebaseUid||
      account?.accountId||
      ''
    ).trim();
    const enabled=!!accountId&&!account?.isGuest;

    for(const card of root.querySelectorAll?.('.char-card[data-id]')||[]){
      const characterId=card.dataset.id;
      const topAccountId=String(
        this.allRankingState.characters?.[characterId]?.[0]?.accountId||
        ''
      ).trim();
      const shouldShow=enabled&&topAccountId===accountId;
      let badge=card.querySelector(':scope > .char-top-player-badge');

      if(shouldShow){
        if(!badge){
          badge=document.createElement('div');
          badge.className='char-top-player-badge';
          badge.textContent='TOP-PLAYER';
          card.appendChild(badge);
        }
        badge.hidden=false;
      }else if(badge){
        badge.remove();
      }

      CharacterCardLayoutService.schedule(
        card
      );
    }
  },
  async loadAllRankings(force=false){
    const state=this.allRankingState;
    const now=Date.now();

    if(
      !force&&
      state.loadedAt&&
      now-state.loadedAt<this.rankingCacheMs
    ){
      this.refreshTopPlayerBadges();
      return state.characters;
    }

    if(state.promise&&!force)return state.promise;

    state.promise=(async()=>{
      const body=await AccountService.request(
        '/ranking/characters?limit=3',
        {method:'GET'}
      );

      const characters=this.normalizeAllRankings(body);
      state.characters=characters;
      state.loadedAt=Date.now();

      for(const [characterId,entries] of Object.entries(characters)){
        this.rankingCache.set(characterId,{
          entries,
          loadedAt:state.loadedAt
        });
      }

      this.refreshTopPlayerBadges();
      return characters;
    })();

    try{
      return await state.promise;
    }finally{
      state.promise=null;
    }
  },
  stats(
    characterId,
    account=AccountState.current
  ){
    const raw=
      account?.characterStats?.[characterId]||{};
    const plays=Math.max(
      0,
      Math.floor(Number(raw.plays)||0)
    );
    const wins=Math.max(
      0,
      Math.floor(Number(raw.wins)||0)
    );
    return {
      plays,
      wins,
      losses:Math.max(
        0,
        Math.floor(
          Number(raw.losses)||
          Math.max(0,plays-wins)
        )
      ),
      winRate:plays>0
        ?wins/plays*100
        :0
    };
  },
  points(
    characterId,
    account=AccountState.current
  ){
    return Math.max(
      0,
      Math.floor(
        Number(
          account?.characterRecords?.[
            characterId
          ]
        )||0
      )
    );
  },
  roman(value){
    return ['', 'I', 'II', 'III', 'IV', 'V'][Math.max(1,Math.min(5,Math.floor(Number(value)||1)))]||'I';
  },
  masterStage(points){
    const value=Math.max(0,Math.round(Number(points)||0));
    if(value>=20000)return {level:5,roman:'V',min:20000};
    if(value>=18000)return {level:4,roman:'IV',min:18000};
    if(value>=16000)return {level:3,roman:'III',min:16000};
    if(value>=14000)return {level:2,roman:'II',min:14000};
    if(value>=12000)return {level:1,roman:'I',min:12000};
    return null;
  },
  tier(points){
    const value=Math.max(0,Math.round(Number(points)||0));
    const master=this.masteryTiers.find(item=>item.id==='master');
    const stage=this.masterStage(value);
    if(master&&stage)return {...master,name:`마스터 ${stage.roman}`,min:stage.min,masterLevel:stage.level,masterRoman:stage.roman};
    return this.masteryTiers.find(item=>value>=item.min)||this.masteryTiers[this.masteryTiers.length-1];
  },
  applyMasterStageBadge(element,points,className='master-stage-badge'){
    if(!element)return null;
    const tier=this.tier(points);
    let badge=element.querySelector(`:scope > .${className}`);
    if(tier.id!=='master'){badge?.remove();return null}
    if(!badge){badge=document.createElement('span');badge.className=className;element.appendChild(badge)}
    badge.textContent=tier.masterRoman||this.roman(tier.masterLevel);
    return badge;
  },

  applyMasteryStyle(
    element,
    characterId,
    className,
    account=AccountState.current
  ){
    if(!element||!characterId)return null;

    const points=account?.isGuest
      ?0
      :this.points(
        characterId,
        account
      );
    const tier=this.tier(points);

    if(className)element.classList.add(className);
    element.dataset.masteryTier=tier.id;
    element.style.setProperty('--mastery-gradient',tier.gradient);
    element.style.setProperty('--mastery-glow',tier.glow);
    return tier;
  },
  applyCardStyle(
    card,
    characterId,
    account=AccountState.current
  ){
    if(!card||!characterId)return;

    // 기본 카드에는 레코드 텍스트를 표시하지 않는다.
    card.querySelector(':scope > .char-mastery')?.remove();

    // 게스트도 일반 계정의 0점과 완전히 같은 none 티어 외곽선을 사용한다.
    const points=
      account?.isGuest
        ?0
        :this.points(
          characterId,
          account
        );
    const tier=this.tier(points);

    card.classList.add('mastery-card');
    card.dataset.masteryTier=tier.id;
    card.style.setProperty(
      '--mastery-gradient',
      tier.gradient
    );
    card.style.setProperty(
      '--mastery-glow',
      tier.glow
    );
    const masterLevel=
      tier.id==='master'
        ?Math.max(
          1,
          Math.min(
            5,
            Number(tier.masterLevel)||1
          )
        )
        :0;
    card.dataset.masterLevel=String(masterLevel);
    this.applyMasterStageBadge(
      card,
      points,
      'master-card-stage'
    );
    CharacterTitleService.attach(
      card,
      characterId,
      points
    );
  },
  applyHudIconStyle(
    icon,
    characterId,
    account=AccountState.current
  ){
    return this.applyMasteryStyle(
      icon,
      characterId,
      'mastery-icon',
      account
    );
  },
  normalizeRanking(payload,characterId){
    const source=
      Array.isArray(payload)?payload:
      Array.isArray(payload?.entries)?payload.entries:
      Array.isArray(payload?.ranking)?payload.ranking:
      Array.isArray(payload?.rankings)?payload.rankings:
      Array.isArray(payload?.data)?payload.data:
      [];

    const seen=new Set();
    const result=[];

    for(const raw of source){
      const accountId=String(
        raw?.accountId??
        raw?.id??
        raw?.userId??
        ''
      )
        .replace(/[\u0000-\u001f\u007f]/g,'')
        .trim()
        .slice(0,128);
      if(!accountId||seen.has(accountId))continue;
      seen.add(accountId);

      const nested=
        raw?.characterRecords&&typeof raw.characterRecords==='object'
          ?raw.characterRecords[characterId]
          :undefined;

      result.push({
        accountId,
        displayName:String((raw?.displayName??raw?.name??accountId)||'이름 없음')
          .replace(/[\u0000-\u001f\u007f]/g,'')
          .trim()||'이름 없음',
        score:Math.max(
          0,
          Math.floor(Number(raw?.score??raw?.points??raw?.masteryPoints??nested)||0)
        )
      });
    }

    return result
      .sort((a,b)=>b.score-a.score||a.displayName.localeCompare(b.displayName,'ko'))
      .slice(0,3);
  },
  async ranking(characterId,force=false){
    if(!ProfileCharacterService.has(characterId))throw new Error('존재하지 않는 캐릭터입니다.');

    const cached=this.rankingCache.get(characterId);
    if(!force&&cached&&Date.now()-cached.loadedAt<this.rankingCacheMs){
      return cached.entries;
    }

    const body=await AccountService.request('/ranking/character',{
      method:'POST',
      body:JSON.stringify({
        charId:characterId,
        limit:3
      })
    });

    const entries=this.normalizeRanking(body,characterId);
    this.rankingCache.set(characterId,{entries,loadedAt:Date.now()});
    return entries;
  },
  resetCardView(card){
    if(!card)return false;

    card
      .querySelector(
        ':scope > .char-record-detail'
      )
      ?.remove();

    delete card.dataset.detailMode;
    delete card.dataset.rankingCharacterId;
    card.classList.remove(
      'record-detail-open',
      'record-ranking-open'
    );

    return true;
  },

  resetGridViews(grid){
    if(!grid)return false;

    for(
      const card of
      grid.querySelectorAll(
        ':scope > .char-card[data-id]'
      )
    ){
      this.resetCardView(card);
    }

    return true;
  },

  detail(card){
    let detail=card.querySelector(':scope > .char-record-detail');
    if(detail)return detail;

    detail=document.createElement('div');
    detail.className='char-record-detail';
    card.appendChild(detail);
    return detail;
  },
  renderStats(card,character){
    const detail=this.detail(card);
    detail.dataset.detailMode='stats';
    detail.replaceChildren();

    const account=
      card._recordAccountData||
      AccountState.current;

    if(account?.isGuest){
      const title=document.createElement('div');
      title.className='char-record-detail-title';
      title.textContent=character.name;

      const empty=document.createElement('div');
      empty.className='char-record-detail-empty';
      empty.textContent='로그인 필요';

      const hint=document.createElement('div');
      hint.className='char-record-detail-hint';
      hint.textContent='우클릭: 캐릭터 랭킹';

      detail.append(title,empty,hint);
      return;
    }

    const stats=this.stats(
      character.id,
      account
    );
    const points=this.points(
      character.id,
      account
    );
    const tier=this.tier(points);

    const title=document.createElement('div');
    title.className='char-record-detail-title';
    title.textContent=character.name;
    detail.appendChild(title);

    const row=(label,value)=>{
      const line=document.createElement('div');
      line.className='char-record-detail-row';
      const key=document.createElement('b');
      key.textContent=label;
      const val=document.createElement('span');
      val.textContent=value;
      line.append(key,val);
      detail.appendChild(line);
    };

    row('플레이',`${stats.plays}회`);
    row('승률',`${stats.plays?stats.winRate.toFixed(1):'0.0'}%`);

    const record=document.createElement('div');
    record.className='char-record-detail-record';

    const recordTop=document.createElement('div');
    recordTop.className='char-record-detail-record-top';

    const recordLabel=document.createElement('b');
    recordLabel.textContent='레코드';

    const recordTier=document.createElement('span');
    recordTier.textContent=tier.name;

    const recordScore=document.createElement('div');
    recordScore.className='char-record-detail-record-score';
    recordScore.textContent=String(points);

    recordTop.append(recordLabel,recordTier);
    record.append(recordTop,recordScore);
    detail.appendChild(record);

    const hint=document.createElement('div');
    hint.className='char-record-detail-hint';
    hint.textContent='우클릭: 캐릭터 랭킹';
    detail.appendChild(hint);
  },
  async renderRanking(card,character){
    const detail=this.detail(card);
    detail.dataset.detailMode='ranking';
    const requestId=`${character.id}:${performance.now()}`;
    detail.dataset.requestId=requestId;
    detail.replaceChildren();

    const title=document.createElement('div');
    title.className='char-record-detail-title ranking-title';

    const name=document.createElement('div');
    name.textContent=character.name;

    const top=document.createElement('div');
    top.textContent='TOP';

    title.append(name,top);
    detail.appendChild(title);

    const loading=document.createElement('div');
    loading.className='char-record-detail-empty';
    loading.textContent='랭킹 불러오는 중…';
    detail.appendChild(loading);

    try{
      const entries=await this.ranking(character.id);
      if(detail.dataset.requestId!==requestId||card.dataset.detailMode!=='ranking')return;

      detail.replaceChildren(title);

      if(!entries.length){
        const empty=document.createElement('div');
        empty.className='char-record-detail-empty';
        empty.textContent='등록된 랭킹이 없습니다.';
        detail.appendChild(empty);
      }else{
        const list=document.createElement('div');
        list.className='char-record-ranking-list';

        entries.forEach((entry,index)=>{
          const row=document.createElement('div');
          row.className='char-record-ranking-row';

          const tier=this.tier(entry.score);
          const borderColor=tier.id==='none'?'#3d4650':tier.text;
          const borderGlow=tier.id==='none'?'rgba(38,46,56,.08)':tier.glow;
          const borderGradient=tier.id==='none'?'linear-gradient(135deg,#27313d,#3a4654)':tier.gradient;
          row.dataset.recordTier=tier.id;
          row.style.setProperty('--ranking-tier-color',borderColor);
          row.style.setProperty('--ranking-tier-glow',borderGlow);
          row.style.setProperty('--ranking-tier-gradient',borderGradient);

          const rank=document.createElement('span');
          rank.className='char-record-ranking-rank';
          rank.textContent=String(index+1);

          const name=document.createElement('span');
          name.className='char-record-ranking-name';
          name.textContent=entry.displayName;

          const score=document.createElement('span');
          score.className='char-record-ranking-score';
          score.textContent=String(entry.score);

          row.append(rank,name,score);
          list.appendChild(row);
        });

        detail.appendChild(list);
      }

      const hint=document.createElement('div');
      hint.className='char-record-detail-hint';
      hint.textContent='우클릭: 카드 앞면';
      detail.appendChild(hint);
    }catch(error){
      if(detail.dataset.requestId!==requestId)return;
      detail.replaceChildren(title);

      const empty=document.createElement('div');
      empty.className='char-record-detail-empty';
      empty.textContent='랭킹을 불러오지 못했습니다.';
      detail.appendChild(empty);
    }
  },
  cycle(card){
    if(!card)return false;
    const character=CharacterCardDataService.get(card.dataset.id);
    if(!character)return false;

    if(!card.classList.contains('record-detail-open')){
      card.classList.add('record-detail-open');
      card.dataset.detailMode='stats';
      this.renderStats(card,character);
      return true;
    }

    if(card.dataset.detailMode==='stats'){
      card.dataset.detailMode='ranking';
      this.renderRanking(card,character);
      return true;
    }

    card.classList.remove('record-detail-open');
    delete card.dataset.detailMode;
    const detail=card.querySelector(':scope > .char-record-detail');
    if(detail)delete detail.dataset.detailMode;
    return true;
  }
});



const MatchResultSubmissionService=Object.freeze({
  queues:new Map(),
  sleep(ms){
    return new Promise(resolve=>setTimeout(resolve,ms));
  },
  accountUid(profile){
    if(profile?.isGuest===true)return '';
    return String(profile?.accountId||'').trim();
  },
  participantSnapshot(){
    const participants=[];
    for(const pid of RoomService.matchPids()){
      const member=RoomService.members.get(pid);
      if(!member||member.spectator===true)continue;
      const uid=this.accountUid(
        pid===RoomService.localPid
          ?PlayerProfileService.snapshot(AccountState.current)
          :member.profile
      );
      if(!uid)return null;
      const characterId=
        OnlineParticipantEntityService.entity(pid)?.character?.id||
        RoomService.duelSelections.get(pid)||
        null;
      if(!characterId)return null;
      participants.push({
        uid,
        pid:String(pid),
        team:String(member.team||''),
        characterId:String(characterId)
      });
    }
    participants.sort((a,b)=>a.pid.localeCompare(b.pid));
    return participants;
  },
  payload(roundPayload){
    const account=AccountState.current;
    if(!account||account.isGuest||account.firebaseAccount!==true)return null;
    const matchId=String(RoomService.serverMatchId||'').trim();
    const roundToken=Math.max(1,Math.floor(Number(roundPayload?.roundToken)||Number(RoomService.roundToken)||1));
    const participants=this.participantSnapshot();
    if(!matchId||!participants||participants.length<2)return null;
    const placements={};
    if(roundPayload?.placements&&typeof roundPayload.placements==='object'){
      for(const participant of participants){
        const value=Math.floor(Number(roundPayload.placements[participant.pid])||0);
        if(value>0)placements[participant.pid]=value;
      }
    }
    return {
      settlementId:`${matchId}:${roundToken}`,
      matchId,
      roundToken,
      mode:String(roundPayload?.mode||RoomService.matchMode||MatchModeService.DUEL),
      participants,
      result:{
        winnerPid:String(roundPayload?.winnerPid||''),
        winnerTeamId:String(roundPayload?.winnerTeamId||''),
        loserPids:[...(roundPayload?.loserPids||[])].map(String).sort(),
        placements,
        ffaTeamCount:Math.max(0,Math.floor(Number(roundPayload?.ffaTeamCount)||0))
      }
    };
  },
  async request(path,body,{forceRefresh=false}={}){
    const fb=globalThis.DuelsFirebase;
    const user=fb?.currentUser?.();
    if(!fb||!user)throw new Error('Firebase 로그인이 필요합니다.');
    const firebaseIdToken=await user.getIdToken(forceRefresh);
    const controller=new AbortController();
    const timeout=setTimeout(()=>controller.abort(),25000);
    let response;
    let data=null;
    try{
      response=await fetch(`${DUELS3_CONFIG.accountApiBase}${path}`,{
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({...body,firebaseIdToken}),
        signal:controller.signal
      });
      try{data=await response.json();}catch{}
    }finally{
      clearTimeout(timeout);
    }
    if(!response.ok||!data?.ok){
      const error=new Error(data?.message||data?.error||`경기 결과 서버 요청 실패 (${response.status})`);
      error.code=data?.error||'';
      error.status=response.status;
      throw error;
    }
    return data;
  },
  async submitRound(roundPayload,submission=this.payload(roundPayload)){
    if(!submission)throw new Error('경기 결과 제출 정보를 만들 수 없습니다.');
    const accountId=String(AccountState.current?.accountId||'');
    const uid=String(globalThis.DuelsFirebase?.currentUser?.()?.uid||'');
    // 방/캐릭터가 변경되어도 같은 경기 ID와 당시 참가자로 재제출한다.
    const snapshot=JSON.parse(JSON.stringify(submission));
    const previous=this.queues.get(accountId)||Promise.resolve();
    const job=previous.catch(()=>{}).then(async()=>{
      let refreshToken=false;
      for(let attempt=0;;attempt+=1){
        if(String(AccountState.current?.accountId||'')!==accountId||
           String(globalThis.DuelsFirebase?.currentUser?.()?.uid||'')!==uid){
          const error=new Error('정산 중 로그인 계정이 변경되었습니다.');
          error.code='account-changed';
          throw error;
        }
        try{
          const latest=await this.request('/match/submit',{submission:snapshot},{forceRefresh:refreshToken});
          refreshToken=false;
          if(latest?.conflict===true){
            const error=new Error('참가자들이 제출한 경기 결과가 서로 일치하지 않습니다.');
            error.code='result-conflict';
            throw error;
          }
          if(latest?.finalized===true&&latest.progress&&latest.result)return latest;
        }catch(error){
          const status=Number(error?.status)||0;
          if(error?.code==='result-conflict')throw error;
          if(status===401&&!refreshToken){
            refreshToken=true;
          }else if(status>=400&&status<500&&![408,425,429].includes(status)){
            throw error;
          }
          // 통신 실패/서버 지연은 정산 거절이 아니다. 같은 ID로 계속 재시도한다.
        }
        await this.sleep(attempt<8?500:Math.min(30000,1000*Math.pow(2,Math.min(5,attempt-8))));
      }
    });
    this.queues.set(accountId,job);
    try{return await job;}finally{
      if(this.queues.get(accountId)===job)this.queues.delete(accountId);
    }
  },
  async submitDeparture({characterId,mode,eventId}={}){
    return this.request('/match/departure/self',{
      characterId:String(characterId||''),
      mode:String(mode||MatchModeService.DUEL),
      eventId:String(eventId||'')
    });
  }
});


const CharacterRecordProgressionService={
  saveQueue:Promise.resolve(),
  resultByRound:new Map(),
  matchGeneration:0,
  departurePenaltyGeneration:-1,
  authoritativeProgress:null,

  settlementEligibility(){
    const local=RoomService.localMember();
    if(
      !local||
      AccountState.current?.isGuest||
      local.spectator===true
    )return {allowed:false,reason:'ineligible'};

    const accountIds=new Set();
    const deviceKeys=new Set();
    for(const pid of RoomService.matchPids()){
      const member=RoomService.members.get(pid);
      if(!member)continue;

      const accountId=AccountService.normalizeId(
        member.profile?.accountId||
        (
          pid===RoomService.localPid
            ?AccountState.current?.accountId
            :''
        )
      );
      if(accountId){
        if(accountIds.has(accountId)){
          return {allowed:false,reason:'same-account'};
        }
        accountIds.add(accountId);
      }

      const deviceKey=String(
        member.deviceKey||
        (
          pid===RoomService.localPid
            ?RoomIdentityService.deviceKey()
            :''
        )||
        ''
      );
      if(deviceKey){
        if(deviceKeys.has(deviceKey)){
          return {allowed:false,reason:'same-device'};
        }
        deviceKeys.add(deviceKey);
      }
    }
    return {allowed:true,reason:'ok'};
  },
  modeValues(mode,tierId,teamSize=1){
    const lower=
      tierId==='none'||
      tierId==='bronze'||
      tierId==='silver'||
      tierId==='gold';

    if(lower)return {win:100,loss:50};
    if(tierId==='diamond')return {win:50,loss:0};
    if(tierId==='platinum')return {win:40,loss:0};
    return {win:30,loss:0};
  },

  teamSize(pid){
    const member=
      RoomService.members.get(pid);
    const teamId=member?.team;
    if(!teamId)return 1;

    return Math.max(
      1,
      RoomService.matchPids().filter(
        memberPid=>
          RoomService.members.get(
            memberPid
          )?.team===teamId
      ).length
    );
  },

  opposingTeamSize(pid){
    const member=RoomService.members.get(pid);
    const ownTeam=member?.team;
    if(!ownTeam)return 1;

    const counts=new Map();
    for(const memberPid of RoomService.matchPids()){
      const teamId=RoomService.members.get(memberPid)?.team;
      if(!teamId||teamId===ownTeam)continue;
      counts.set(
        teamId,
        (counts.get(teamId)||0)+1
      );
    }

    let largest=1;
    for(const count of counts.values()){
      largest=Math.max(largest,count);
    }
    return largest;
  },

  teamWinMultiplier(pid){
    const ownSize=this.teamSize(pid);
    const opposingSize=this.opposingTeamSize(pid);

    if(opposingSize===1&&(ownSize===2||ownSize===3)){
      return 1/ownSize;
    }
    if(ownSize===1&&opposingSize===2)return 1.5;
    if(ownSize===1&&opposingSize===3)return 2;
    return 1;
  },

  won(payload,pid){
    if(
      payload?.teamVictory&&
      payload?.winnerTeamId
    ){
      return (
        RoomService.members.get(pid)?.team===
        payload.winnerTeamId
      );
    }
    return String(payload?.winnerPid||'')===
      String(pid||'');
  },

  placement(payload,pid){
    const value=
      Number(
        payload?.placements?.[
          String(pid||'')
        ]
      );

    return Number.isFinite(value)&&value>=1
      ?Math.floor(value)
      :null;
  },

  ffaTeamCount(payload){
    const explicit=Math.floor(Number(payload?.ffaTeamCount)||0);
    if(explicit>0)return explicit;

    let maximum=0;
    for(const value of Object.values(payload?.placements||{})){
      const placement=Math.floor(Number(value)||0);
      if(placement>maximum)maximum=placement;
    }
    return Math.max(1,maximum);
  },
  ffaOutcome(payload,pid){
    const placement=this.placement(payload,pid);
    if(placement===null)return null;

    const teamCount=this.ffaTeamCount(payload);
    if(placement===1)return 'win';
    if(placement===teamCount)return 'loss';
    return 'neutral';
  },
  ffaScoreMultiplier(payload,pid){
    const placement=this.placement(payload,pid);
    const teamCount=this.ffaTeamCount(payload);
    if(placement===null)return {kind:'neutral',multiplier:0};
    if(placement>=teamCount)return {kind:'loss',multiplier:1};

    if(placement===1){
      const imbalance=this.teamWinMultiplier(pid);
      if(imbalance!==1){
        return {kind:'win',multiplier:imbalance};
      }
    }

    if(teamCount>=4){
      if(placement===1)return {kind:'win',multiplier:4};
      if(placement===2)return {kind:'neutral',multiplier:2};
      return {kind:'neutral',multiplier:1};
    }
    if(teamCount===3){
      if(placement===1)return {kind:'win',multiplier:3};
      return {kind:'neutral',multiplier:1};
    }

    if(placement===1){
      return {kind:'win',multiplier:this.teamWinMultiplier(pid)};
    }
    return {kind:'loss',multiplier:1};
  },

  characterId(pid){
    const entity=
      OnlineParticipantEntityService.entity(
        pid
      );
    return (
      entity?.character?.id||
      RoomService.duelSelections.get(pid)||
      null
    );
  },

  captureAuthoritativeProgress(
    account=AccountState.current
  ){
    if(
      this.authoritativeProgress||
      !account
    ){
      return this.authoritativeProgress;
    }

    this.authoritativeProgress={
      characterRecords:{
        ...(account.characterRecords||{})
      },
      characterStats:{
        ...(account.characterStats||{})
      }
    };

    return this.authoritativeProgress;
  },

  setAuthoritativeProgress(progress){
    if(!progress)return null;

    this.authoritativeProgress={
      characterRecords:{
        ...(progress.characterRecords||{})
      },
      characterStats:{
        ...(progress.characterStats||{})
      }
    };

    return this.authoritativeProgress;
  },

  syncLocalRecordPresentation(
    characterIds=[],
    reason='round-result-optimistic',
    broadcast=true
  ){
    const account=
      AccountState.current;

    if(
      !account||
      account.isGuest
    ){
      return false;
    }

    const localMember=
      RoomService.localMember();

    const profileSnapshot=
      PlayerProfileService.snapshot(
        account
      );

    if(localMember){
      localMember.profile=
        profileSnapshot;
    }

    const uniqueIds=[
      ...new Set(
        (characterIds||[])
          .map(id=>String(id||''))
          .filter(Boolean)
      )
    ];

    for(const characterId of uniqueIds){
      GameEvents.emit(
        'character-record-changed',
        {
          pid:
            RoomService.localPid,
          characterId,
          points:
            CharacterRecordService.points(
              characterId,
              account
            ),
          stats:
            account
              .characterStats
              ?.[characterId]||
            null,
          profile:
            profileSnapshot,
          local:true,
          reason
        }
      );
    }

    if(
      broadcast&&
      Training.sessionMode==='online'&&
      OnlineDuelService.active&&
      uniqueIds.length
    ){
      for(const characterId of uniqueIds){
        RoomService.sendGameplay({
          type:'duel-record-update',
          roundToken:
            OnlineDuelService.roundToken,
          characterId,
          points:
            CharacterRecordService.points(
              characterId,
              account
            ),
          stats:
            account
              .characterStats
              ?.[characterId]||
            null,
          profile:
            profileSnapshot,
          provisional:
            reason.includes(
              'optimistic'
            )
        });
      }
    }

    return true;
  },

  applyOptimisticRecord(
    result,
    {
      broadcast=true,
      reason='round-result-optimistic'
    }={}
  ){
    const account=
      AccountState.current;

    if(
      !account||
      !result?.characterId
    ){
      return false;
    }

    const characterId=
      String(result.characterId);

    account.characterRecords={
      ...(account.characterRecords||{}),
      [characterId]:
        Math.max(
          0,
          Math.floor(
            Number(result.after)||0
          )
        )
    };

    account.recordSettlementPending=true;

    AccountState.current=
      account;

    this.syncLocalRecordPresentation(
      [characterId],
      reason,
      broadcast
    );

    return true;
  },

  rebuildOptimisticProjection({
    broadcast=true,
    reason='round-result-optimistic-reconcile'
  }={}){
    const account=
      AccountState.current;

    const base=
      this.authoritativeProgress;

    if(
      !account||
      !base
    ){
      return false;
    }

    account.characterRecords={
      ...(base.characterRecords||{})
    };

    account.characterStats={
      ...(base.characterStats||{})
    };

    const touched=
      new Set();

    const pendingEntries=[
      ...this.resultByRound.entries()
    ]
      .filter(([,entry])=>
        entry?.pending===true&&
        entry?.payload&&entry.accountId===String(account.accountId||'')
      )
      .sort(([,a],[,b])=>
        (
          Number(a?.generation)||0
        )-
        (
          Number(b?.generation)||0
        )||Number(a?.token)-Number(b?.token)
      );

    for(const [key,entry] of pendingEntries){
      const projected=
        this.optimisticRoundResult(
          entry.payload,
          entry.pid||
            RoomService.localPid,
          account,
          entry.optimistic
        );

      if(!projected)continue;

      account.characterRecords={
        ...(account.characterRecords||{}),
        [projected.characterId]:
          projected.after
      };

      touched.add(
        projected.characterId
      );

      this.resultByRound.set(
        key,
        {
          ...entry,
          delta:
            projected.delta,
          optimistic:
            projected
        }
      );
    }

    account.recordSettlementPending=
      pendingEntries.length>0;

    AccountState.current=
      account;

    this.syncLocalRecordPresentation(
      [...touched],
      reason,
      broadcast
    );

    return true;
  },

  showRecordCorrection(
    fromScore,
    toScore,
    label='레코드 정정'
  ){
    let element=
      document.getElementById(
        'record-delta-toast'
      );

    if(!element){
      element=
        document.createElement(
          'div'
        );
      element.id=
        'record-delta-toast';
      element.className=
        'record-delta-toast';
      document.body.appendChild(
        element
      );
    }

    const from=
      Number(fromScore)||0;
    const to=
      Number(toScore)||0;

    element.textContent=
      `${label} · ${from} → ${to}`;

    element.style.color=
      to<from
        ?'#ff8585'
        :to>from
          ?'#7fffa0'
          :'#aab6c2';

    element.classList.remove(
      'show'
    );

    void element.offsetWidth;

    element.classList.add(
      'show'
    );

    clearTimeout(
      this._recordDeltaToastTimer
    );

    this._recordDeltaToastTimer=
      setTimeout(()=>{
        element.classList.remove(
          'show'
        );
      },4000);

    return true;
  },

  optimisticRoundResult(payload,pid,account,snapshot=null){
    const characterId=
      snapshot?.characterId||this.characterId(pid);

    if(!characterId)return null;

    const before=
      Math.max(
        0,
        Math.floor(
          Number(
            account
              ?.characterRecords
              ?.[characterId]
          )||0
        )
      );

    const tier=
      CharacterRecordService.tier(
        before
      );

    const values=
      this.modeValues(
        payload?.mode,
        tier.id
      );

    const mode=
      String(
        snapshot?.mode||payload?.mode||
        RoomService.matchMode||
        MatchModeService.DUEL
      );

    const placement=
      snapshot?snapshot.placement:mode===MatchModeService.FFA
        ?this.placement(
            payload,
            pid
          )
        :null;

    const ffaOutcome=
      snapshot?snapshot.outcome:mode===MatchModeService.FFA
        ?this.ffaOutcome(
            payload,
            pid
          )
        :null;

    const won=
      snapshot?snapshot.outcome==='win':mode===MatchModeService.FFA
        ?(
            ffaOutcome==='win'
              ?true
              :ffaOutcome==='loss'
                ?false
                :null
          )
        :this.won(
            payload,
            pid
          );

    const ffaScore=
      snapshot?.ffaScore||(mode===MatchModeService.FFA
        ?this.ffaScoreMultiplier(
            payload,
            pid
          )
        :null);

    const requestedDelta=
      Math.round(
        mode===MatchModeService.FFA
          ?(
              ffaScore?.kind==='loss'
                ?values.loss*
                  (
                    ffaScore?.multiplier||
                    1
                  )
                :values.win*
                  (
                    ffaScore?.multiplier||
                    1
                  )
            )
          :mode===MatchModeService.TEAM
            ?(
                won
                  ?values.win*3
                  :values.loss
              )
            :(
                won
                  ?values.win
                  :values.loss
              )
      );

    const floor=
      Math.max(
        0,
        Number(tier.min)||0
      );

    const after=
      Math.round(
        requestedDelta<0
          ?Math.max(
              floor,
              before+
                requestedDelta
            )
          :before+
            requestedDelta
      );

    return {
      token:
        Math.max(
          1,
          Number(
            payload?.roundToken
          )||1
        ),
      characterId,
      before,
      after,
      delta:
        after-before,
      requestedDelta,
      mode,
      placement,
      ffaScore,
      outcome:
        mode===MatchModeService.FFA
          ?(
              ffaOutcome||
              'neutral'
            )
          :won
            ?'win'
            :'loss',
      optimistic:true
    };
  },

  showRecordDelta(result){
    if(
      !result||
      result.blocked
    )return false;

    let element=
      document.getElementById(
        'record-delta-toast'
      );

    if(!element){
      element=
        document.createElement('div');
      element.id='record-delta-toast';
      element.className='record-delta-toast';
      document.body.appendChild(element);
    }

    const delta=
      Number(result.delta)||0;
    const sign=
      delta>0
        ?'+'
        :'';

    element.textContent=
      `레코드 ${sign}${delta} · ${result.before} → ${result.after}`;

    element.style.color=
      delta>0
        ?'#7fffa0'
        :delta<0
          ?'#ff8585'
          :'#aab6c2';

    element.classList.remove('show');
    void element.offsetWidth;
    element.classList.add('show');

    clearTimeout(
      this._recordDeltaToastTimer
    );

    this._recordDeltaToastTimer=
      setTimeout(()=>{
        element.classList.remove(
          'show'
        );
      },8000);

    return true;
  },

  scheduleSave(){
    return Promise.resolve(null);
  },

  applyServerProgress(progress,result,payload,resultKey){
    const account=
      AccountState.current;

    if(
      !account||
      account.isGuest||
      !progress
    ){
      return null;
    }

    const previousResult=
      this.resultByRound.get(
        resultKey
      );

    const previousOptimistic=
      previousResult?.optimistic||
      null;

    this.setAuthoritativeProgress(
      progress
    );

    account.characterRecords={
      ...(progress.characterRecords||{})
    };

    account.characterStats={
      ...(progress.characterStats||{})
    };

    account.recordSettlementPending=false;

    AccountState.current=
      account;

    const characterId=
      String(
        result?.characterId||''
      );

    const after=
      CharacterRecordService.points(
        characterId,
        account
      );
    const serverResult={
      token:Math.max(1,Number(payload?.roundToken)||1),
      characterId,
      won:result?.outcome==='win',
      mode:String(result?.mode||payload?.mode||RoomService.matchMode||MatchModeService.DUEL),
      placement:Number.isFinite(Number(result?.placement))?Number(result.placement):null,
      outcome:String(result?.outcome||'neutral'),
      ffaTeamCount:Number(result?.ffaTeamCount)||null,
      scoreMultiplier:Number(result?.scoreMultiplier)||1,
      teamSize:Number(result?.teamSize)||1,
      before:Number(result?.before)||0,
      after,
      delta:Number(result?.delta)||0,
      requestedDelta:Number(result?.requestedDelta)||0,
      tierBefore:CharacterRecordService.tier(Number(result?.before)||0),
      tierAfter:CharacterRecordService.tier(after),
      finalized:true
    };
    this.resultByRound.set(
      resultKey,
      serverResult
    );

    /*
     * 서버 확정값을 기준점으로 삼고, 혹시 뒤 라운드의
     * 낙관적 정산이 아직 남아 있다면 그 값만 다시 얹는다.
     */
    this.rebuildOptimisticProjection({
      broadcast:false,
      reason:'round-result-server-reconcile'
    });

    const profileSnapshot=
      PlayerProfileService.snapshot(
        AccountState.current
      );
    const localMember=
      RoomService.localMember();

    if(localMember){
      localMember.profile=
        profileSnapshot;
    }

    GameEvents.emit('character-record-changed',{
      pid:RoomService.localPid,
      characterId,
      points:
        CharacterRecordService.points(
          characterId,
          AccountState.current
        ),
      stats:AccountState.current?.characterStats?.[characterId]||null,
      profile:profileSnapshot,
      local:true,
      reason:'round-result'
    });
    if(Training.sessionMode==='online'&&OnlineDuelService.active){
      RoomService.sendGameplay({
        type:'duel-record-update',
        roundToken:OnlineDuelService.roundToken,
        characterId,
        points:
          CharacterRecordService.points(
            characterId,
            AccountState.current
          ),
        stats:AccountState.current?.characterStats?.[characterId]||null,
        profile:profileSnapshot
      });
    }
    CharacterRecordService.clearRankingCache();
    CharacterRecordService.loadAllRankings(true).catch(error=>{
      console.warn('[Duels] ranking refresh failed after settlement',error);
    });
    const sameAsOptimistic=
      previousOptimistic&&
      Number(
        previousOptimistic.before
      )===
        Number(
          serverResult.before
        )&&
      Number(
        previousOptimistic.after
      )===
        Number(
          serverResult.after
        )&&
      Number(
        previousOptimistic.delta
      )===
        Number(
          serverResult.delta
        );

    if(
      previousOptimistic&&
      !sameAsOptimistic
    ){
      this.showRecordCorrection(
        previousOptimistic.after,
        serverResult.after,
        '레코드 서버 정정'
      );
    }else if(!previousOptimistic){
      this.showRecordDelta(
        serverResult
      );
    }

    return serverResult;
  },

  applyRoundResult(payload){
    const pid=RoomService.localPid;
    const account=AccountState.current;
    const token=Math.max(1,Number(payload?.roundToken)||1);
    if(
      !pid||
      !account||
      account.isGuest||
      account.firebaseAccount!==true||
      RoomService.localMember()?.spectator===true
    )return null;
    const resultKey=`${this.matchGeneration}:${token}`;
    if(this.resultByRound.has(resultKey)){
      return this.resultByRound.get(resultKey);
    }
    const eligibility=this.settlementEligibility();
    if(!eligibility.allowed){
      const blocked={token,blocked:true,reason:eligibility.reason,delta:0};
      this.resultByRound.set(resultKey,blocked);
      return blocked;
    }
    const submission=MatchResultSubmissionService.payload(payload);
    if(!submission)return null;
    const accountId=String(account.accountId||'');
    const optimistic=
      this.optimisticRoundResult(
        payload,
        pid,
        account
      );

    this.captureAuthoritativeProgress(
      account
    );

    const pending={
      token,
      generation:this.matchGeneration,
      accountId,
      pending:true,
      delta:
        Number(
          optimistic?.delta
        )||0,
      mode:
        payload?.mode||
        RoomService.matchMode||
        MatchModeService.DUEL,
      optimistic,
      payload,
      pid
    };

    this.resultByRound.set(
      resultKey,
      pending
    );

    if(optimistic){
      /*
       * 여기서 토스트만 미리 띄우는 것이 아니라 실제 로컬
       * characterRecords 값까지 즉시 바꾼다.
       * Firebase/Worker 저장은 하지 않는다.
       */
      this.applyOptimisticRecord(
        optimistic,
        {
          broadcast:true,
          reason:'round-result-optimistic'
        }
      );

      this.showRecordDelta(
        optimistic
      );
    }

    MatchResultSubmissionService
      .submitRound(payload,submission)
      .then(response=>{
        if(String(AccountState.current?.accountId||'')!==accountId)return;
        if(response?.finalized!==true)return;
        this.applyServerProgress(
          response.progress,
          response.result,
          payload,
          resultKey
        );
      })
      .catch(error=>{
        if(String(AccountState.current?.accountId||'')!==accountId){
          this.resultByRound.delete(resultKey);
          return;
        }
        console.warn(
          '[Duels] match settlement failed',
          error
        );
        // 확정 후 UI 갱신 오류가 나더라도 서버 정산을 취소한 것으로 처리하지 않는다.
        if(this.resultByRound.get(resultKey)?.finalized===true)return;

        const provisional=
          this.resultByRound.get(
            resultKey
          )?.optimistic||
          optimistic;

        this.resultByRound.delete(
          resultKey
        );

        this.rebuildOptimisticProjection({
          broadcast:true,
          reason:'round-result-optimistic-rollback'
        });

        if(provisional){
          const restored=
            CharacterRecordService.points(
              provisional.characterId,
              AccountState.current
            );

          this.showRecordCorrection(
            provisional.after,
            restored,
            '레코드 정산 오류 · 점수 회수'
          );
        }
      });
    return pending;
  },

  applyDeparturePenalty(){
    const pid=RoomService.localPid;
    const account=AccountState.current;
    const member=RoomService.localMember();
    if(
      !pid||
      !account||
      account.isGuest||
      account.firebaseAccount!==true||
      member?.spectator===true||
      this.departurePenaltyGeneration===this.matchGeneration
    ){
      return null;
    }
    const activePhases=new Set([
      'playing',
      'round-result',
      'between',
      'between-countdown'
    ]);
    if(!activePhases.has(String(RoomService.duelPhase||''))){
      return null;
    }
    const eligibility=this.settlementEligibility();
    if(!eligibility.allowed){
      return {blocked:true,reason:eligibility.reason,delta:0};
    }
    const characterId=this.characterId(pid);
    if(!characterId)return null;
    const mode=RoomService.matchMode||OnlineDuelService.mode||MatchModeService.DUEL;
    const eventId=`${String(RoomService.serverMatchId||'match')}:departure:${this.matchGeneration}:${pid}`;
    this.departurePenaltyGeneration=this.matchGeneration;
    MatchResultSubmissionService
      .submitDeparture({characterId,mode,eventId})
      .then(response=>{
        const progress=response?.progress;
        const result=response?.result;
        if(!progress||!result)return;
        this.setAuthoritativeProgress(
          progress
        );
        account.characterRecords={...(progress.characterRecords||{})};
        account.characterStats={...(progress.characterStats||{})};
        account.recordSettlementPending=false;
        AccountState.current=account;
        const localMember=RoomService.localMember();
        if(localMember){
          localMember.profile=PlayerProfileService.snapshot(account);
        }
        const after=CharacterRecordService.points(characterId,account);
        const profileSnapshot=PlayerProfileService.snapshot(account);
        GameEvents.emit('character-record-changed',{
          pid,
          characterId,
          points:after,
          stats:account.characterStats?.[characterId]||null,
          profile:profileSnapshot,
          local:true,
          reason:'mid-match-departure'
        });
        CharacterRecordService.clearRankingCache();
        CharacterRecordService.loadAllRankings(true).catch(error=>{
          console.warn('[Duels] ranking refresh failed after departure',error);
        });
        this.showRecordDelta({
          characterId,
          before:Number(result.before)||0,
          after,
          delta:Number(result.delta)||0,
          requestedDelta:Number(result.requestedDelta)||0
        });
      })
      .catch(error=>{
        console.warn('[Duels] departure penalty save failed',error);
        this.departurePenaltyGeneration=-1;
      });
    return {
      pending:true,
      characterId,
      eventId
    };
  },

  reset(){
    this.matchGeneration+=1;
    const accountId=String(AccountState.current?.accountId||'');
    for(const [key,entry] of this.resultByRound){
      if(entry?.pending!==true||entry.accountId!==accountId)this.resultByRound.delete(key);
    }
    this.departurePenaltyGeneration=-1;
    if(!this.resultByRound.size)this.authoritativeProgress=null;

    if(AccountState.current){
      AccountState.current.recordSettlementPending=this.resultByRound.size>0;
    }
  }
};

/* 레코드 실시간 UI 동기화 */
const CharacterRecordLiveRefreshService=Object.freeze({
  profileFor(pid,fallback=null){
    const id=String(pid||'');

    if(
      !id||
      id===String(RoomService.localPid||'')
    ){
      return AccountState.current||fallback;
    }

    return (
      RoomService.members.get(id)?.profile||
      fallback||
      null
    );
  },

  updateTooltip(node,characterId,profile){
    if(!node||!characterId)return false;

    const character=
      GAME_DATA.characters[characterId]||
      null;
    if(!character)return false;

    const tooltip=
      node.matches?.('.char-tooltip')
        ?node
        :node.querySelector?.(
          ':scope > .char-tooltip'
        );

    if(!tooltip)return false;

    tooltip.innerHTML=
      CharacterDescriptionService.html(
        character,
        {
          recordPoints:
            CharacterRecordService.points(
              characterId,
              profile
            )
        }
      );

    return true;
  },

  updateCard(card,characterId,profile){
    if(!card||!characterId)return false;

    card._recordAccountData=
      profile||
      card._recordAccountData||
      AccountState.current;

    CharacterRecordService.applyCardStyle(
      card,
      characterId,
      card._recordAccountData
    );

    this.updateTooltip(
      card,
      characterId,
      card._recordAccountData
    );

    if(
      card.classList.contains(
        'record-detail-open'
      )&&
      card.dataset.detailMode==='stats'
    ){
      const character=
        CharacterCardDataService.get(
          characterId
        );
      if(character){
        CharacterRecordService.renderStats(
          card,
          character
        );
      }
    }

    return true;
  },

  ownerPid(node){
    return String(
      node?.dataset?.masteryPid||
      node?.dataset?.pid||
      ''
    );
  },

  matchesOwner(node,pid,isLocal){
    const ownerPid=this.ownerPid(node);

    if(ownerPid){
      return ownerPid===String(pid||'');
    }

    return isLocal;
  },

  refresh({
    pid=null,
    characterId=null,
    profile=null
  }={}){
    const id=String(characterId||'');
    if(!id)return false;

    const resolvedPid=
      String(pid||RoomService.localPid||'');
    const isLocal=
      !resolvedPid||
      resolvedPid===String(RoomService.localPid||'');

    const resolvedProfile=
      profile||
      this.profileFor(
        resolvedPid,
        isLocal
          ?AccountState.current
          :null
      );

    if(!resolvedProfile)return false;

    // 이미 존재하는 모든 캐릭터 카드: 선택창/시작 증강/라운드 준비 포함.
    for(
      const card of
      document.querySelectorAll(
        `.char-card[data-id="${CSS.escape(id)}"]`
      )
    ){
      if(
        !this.matchesOwner(
          card,
          resolvedPid,
          isLocal
        )
      )continue;

      this.updateCard(
        card,
        id,
        resolvedProfile
      );
    }

    // 카드가 아닌 캐릭터 버튼/HUD 아이콘/훈련장 캐릭터 툴팁.
    for(
      const node of
      document.querySelectorAll(
        `[data-char-tooltip="true"][data-id="${CSS.escape(id)}"]`
      )
    ){
      if(node.classList.contains('char-card'))continue;

      if(
        !this.matchesOwner(
          node,
          resolvedPid,
          isLocal
        )
      )continue;

      CharacterRecordService.applyHudIconStyle(
        node,
        id,
        resolvedProfile
      );
      this.updateTooltip(
        node,
        id,
        resolvedProfile
      );
    }

    // 로컬 프로필은 메인 캐릭터 레코드/등급/칭호가 즉시 다시 계산되어야 한다.
    if(isLocal){
      if(
        typeof ProfileSettingsUI!=='undefined'
      ){
        ProfileSettingsUI.render();
      }
    }

    // 방 프로필은 해당 PID의 최신 snapshot을 읽어 다시 그린다.
    if(
      typeof RoomUI!=='undefined'&&
      !document
        .getElementById('scr-room')
        ?.classList.contains('hidden')
    ){
      RoomUI.render();
    }

    // 전투 HUD는 참가자별 profile/record를 다시 읽어 즉시 반영한다.
    if(
      typeof Training!=='undefined'&&
      Training.active
    ){
      Training.renderAugHud();
    }

    if(
      typeof OnlineDuelService!=='undefined'&&
      OnlineDuelService.active&&
      typeof OnlineDuelService
        .renderCharacterPreviews==='function'
    ){
      OnlineDuelService
        .renderCharacterPreviews();
    }

    return true;
  }
});

/* 플레이어 프로필 상세 */
const PlayerProfileDetailService=Object.freeze({
  overallFromAccount(account){
    const stats=account?.characterStats||{};
    let plays=0;
    let wins=0;
    let losses=0;

    for(const character of ProfileCharacterService.all()){
      const raw=stats[character.id]||{};
      const characterPlays=Math.max(0,Math.floor(Number(raw.plays)||0));
      const characterWins=Math.max(0,Math.floor(Number(raw.wins)||0));
      const characterLosses=Math.max(
        0,
        Math.floor(
          Number(raw.losses)||
          Math.max(0,characterPlays-characterWins)
        )
      );

      plays+=characterPlays;
      wins+=characterWins;
      losses+=characterLosses;
    }

    return {
      plays,
      wins,
      losses,
      winRate:plays>0?wins/plays*100:0
    };
  },
  topRecordsFromAccount(account,limit=3){
    const records=account?.characterRecords||[];
    const entries=[];

    const characters=ProfileCharacterService.all();

    for(let index=0;index<characters.length;index++){
      const character=characters[index];
      const score=Math.max(
        0,
        Math.floor(Number(records[character.id])||0)
      );

      entries.push({
        characterId:character.id,
        characterName:character.name,
        score,
        order:index
      });
    }

    entries.sort((a,b)=>{
      if(b.score!==a.score)return b.score-a.score;
      return a.order-b.order;
    });

    return entries.slice(0,Math.max(0,Number(limit)||0));
  },
  payload(account=AccountState.current){
    return {
      overall:this.overallFromAccount(account),
      topRecords:this.topRecordsFromAccount(account,3)
    };
  },
  normalize(profile){
    const overall=profile?.overallStats||{};
    const topRecords=Array.isArray(profile?.topRecords)?profile.topRecords:[];

    return {
      overall:{
        plays:Math.max(0,Math.floor(Number(overall.plays)||0)),
        wins:Math.max(0,Math.floor(Number(overall.wins)||0)),
        losses:Math.max(0,Math.floor(Number(overall.losses)||0)),
        winRate:Math.max(0,Number(overall.winRate)||0)
      },
      topRecords:topRecords
        .filter(entry=>ProfileCharacterService.has(entry?.characterId))
        .map(entry=>({
          characterId:entry.characterId,
          characterName:
            ProfileCharacterService.get(entry.characterId)?.name||
            String(entry.characterName||entry.characterId),
          score:Math.max(0,Math.floor(Number(entry.score)||0))
        }))
        .sort((a,b)=>b.score-a.score)
        .slice(0,3)
    };
  }
});

/* 플레이어 프로필 */
const PlayerProfileService=Object.freeze({
  highestRecordCharacter(account=AccountState.current){
    const characters=ProfileCharacterService.all();
    if(!characters.length)return null;

    const records=account?.characterRecords||{};
    let best=characters[0];
    let bestScore=-Infinity;

    for(const character of characters){
      const score=Math.max(0,Number(records[character.id])||0);
      if(score>bestScore){
        best=character;
        bestScore=score;
      }
    }

    return best?.id||null;
  },
  normalizeMainCharacter(account=AccountState.current){
    const explicit=
      account?.mainCharacterExplicit===true||
      account?.profile?.mainCharacterExplicit===true;
    const requested=String(
      account?.mainCharacterId||
      account?.profile?.mainCharacterId||
      ''
    );

    if(explicit&&ProfileCharacterService.has(requested)){
      return requested;
    }

    return (
      this.highestRecordCharacter(account)||
      ProfileCharacterService.all()[0]?.id||
      null
    );
  },
  isAutomatic(account=AccountState.current){
    return !(
      account?.mainCharacterExplicit===true||
      account?.profile?.mainCharacterExplicit===true
    );
  },
  snapshot(account=AccountState.current){
    const mainCharacterId=this.normalizeMainCharacter(account);
    const character=ProfileCharacterService.get(mainCharacterId);

    const detail=PlayerProfileDetailService.payload(account);
    const recordPoints=
      Math.max(
        0,
        Math.floor(
          Number(
            account?.characterRecords?.[
              mainCharacterId
            ]
          )||0
        )
      );

    return {
      accountId:String(account?.accountId||'guest'),
      displayName:String(account?.displayName||'게스트').trim().slice(0,24)||'게스트',
      isGuest:!!account?.isGuest,
      mainCharacterId,
      mainCharacterName:character?.name||mainCharacterId||'-',
      mainCharacterTitle:
        (
          CharacterRecordService.tier(
            recordPoints
          ).id==='master'&&
          Number(
            CharacterRecordService.tier(
              recordPoints
            ).masterLevel
          )>=5
        )
          ?CharacterTitleService.get(
            mainCharacterId
          )
          :'',
      color:character?.color||'#8292a0',
      image:ProfileCharacterImageService.source(mainCharacterId),
      recordPoints,
      characterRecords:Object.fromEntries(
        ProfileCharacterService.all().map(character=>[
          character.id,
          Math.max(
            0,
            Math.floor(
              Number(account?.characterRecords?.[character.id])||0
            )
          )
        ])
      ),
      characterStats:Object.fromEntries(
        ProfileCharacterService.all().map(character=>{
          const raw=
            account?.characterStats?.[character.id]||{};
          const plays=Math.max(
            0,
            Math.floor(Number(raw.plays)||0)
          );
          const wins=Math.max(
            0,
            Math.floor(Number(raw.wins)||0)
          );
          const losses=Math.max(
            0,
            Math.floor(
              Number(raw.losses)||
              Math.max(0,plays-wins)
            )
          );

          return [
            character.id,
            {
              plays,
              wins,
              losses
            }
          ];
        })
      ),
      overallStats:detail.overall,
      topRecords:detail.topRecords,
      mainCharacterAutomatic:this.isAutomatic(account)
    };
  },
  async setMainCharacter(characterId){
    const account=AccountState.current;
    if(!account||!ProfileCharacterService.has(characterId))return false;

    account.mainCharacterId=characterId;
    account.mainCharacterExplicit=true;
    account.profile={
      ...(account.profile||{}),
      mainCharacterId:characterId,
      mainCharacterExplicit:true
    };

    if(!account.isGuest){
      AccountState.current=
        await FirebaseProfilePersistenceService.save(
          account
        );
    }

    return true;
  }
});

/* 태그 */
const attackTagCache=new WeakMap();

const WorldBoundsService=Object.freeze({
  width(){
    const map=
      typeof DebugMapService!=='undefined'
        ?DebugMapService.current?.()
        :null;
    return Math.max(
      GAME_DATA.canvas.width,
      Number(map?.worldWidth)||
        GAME_DATA.world.width
    );
  },
  height(){
    const map=
      typeof DebugMapService!=='undefined'
        ?DebugMapService.current?.()
        :null;
    return Math.max(
      GAME_DATA.canvas.height,
      Number(map?.worldHeight)||
        GAME_DATA.world.height
    );
  },
});

const MatchSpawnService=Object.freeze({
  shuffled(ids){
    const out=[...(ids||[])];
    for(let index=out.length-1;index>0;index--){
      const random=
        globalThis.crypto?.getRandomValues
          ?globalThis.crypto.getRandomValues(new Uint32Array(1))[0]/4294967296
          :Math.random();
      const swap=Math.floor(random*(index+1));
      [out[index],out[swap]]=[out[swap],out[index]];
    }
    return out;
  },
  pointClear(x,y,clearance=28){
    const width=WorldBoundsService.width();
    const height=WorldBoundsService.height();

    if(
      x-clearance<0||
      y-clearance<0||
      x+clearance>width||
      y+clearance>height
    )return false;

    const walls=
      typeof DebugMapService!=='undefined'
        ?DebugMapService.walls()
        :[];

    return !walls.some(wall=>
      x+clearance>=wall.x&&
      x-clearance<=wall.x+wall.w&&
      y+clearance>=wall.y&&
      y-clearance<=wall.y+wall.h
    );
  },
  polygon(ids,rotation,radius,width,height){
    const out={};
    const cx=width*.5;
    const cy=height*.5;

    ids.forEach((pid,index)=>{
      const angle=
        rotation+
        Math.PI*2*index/ids.length;
      out[pid]={
        x:cx+Math.cos(angle)*radius,
        y:cy+Math.sin(angle)*radius
      };
    });

    return out;
  },
  pointMap(
    pids,
    mode,
    teamByPid={}
  ){
    const ids=[...(pids||[])];
    if(!MatchModeService.isFfa(mode)){
      ids.sort(
        (a,b)=>String(a).localeCompare(String(b))
      );
    }
    const width=WorldBoundsService.width();
    const height=WorldBoundsService.height();
    const out={};

    if(
      MatchModeService.isTeam(mode)&&
      ids.length===4
    ){
      const groups=new Map();

      for(const pid of ids){
        const team=
          teamByPid?.[pid]||
          RoomService.members.get(pid)?.team||
          pid;

        if(!groups.has(team)){
          groups.set(team,[]);
        }
        groups.get(team).push(pid);
      }

      const teamIds=[
        ...groups.keys()
      ].sort((a,b)=>
        String(a).localeCompare(String(b))
      );

      if(
        teamIds.length===2&&
        teamIds.every(team=>
          groups.get(team).length===2
        )
      ){
        const spawnX=[
          width*.16,
          width*.84
        ];
        const verticalGap=
          Math.min(
            90,
            height*.07
          );

        teamIds.forEach((team,index)=>{
          const members=[
            ...groups.get(team)
          ].sort((a,b)=>
            String(a).localeCompare(String(b))
          );
          const centerY=height*.5;

          out[members[0]]={
            x:spawnX[index],
            y:centerY-verticalGap
          };
          out[members[1]]={
            x:spawnX[index],
            y:centerY+verticalGap
          };
        });

        if(
          ids.every(pid=>
            this.pointClear(
              out[pid].x,
              out[pid].y
            )
          )
        ){
          return out;
        }
      }
    }

    if(
      ids.length===2&&
      !MatchModeService.isFfa(mode)&&
      !MatchModeService.isTeam(mode)
    ){
      out[ids[0]]={
        x:width*.20,
        y:height*.50
      };
      out[ids[1]]={
        x:width*.80,
        y:height*.50
      };
      return out;
    }

    const baseRadius=
      Math.min(width,height);
    const radiusRatios=[
      .33,
      .30,
      .36,
      .27,
      .39,
      .24,
      .42,
      .21
    ];
    const baseRotation=-Math.PI/2;

    // 모든 참가자의 반지름을 한꺼번에 바꾸고 전체 정다각형을 함께 회전한다.
    // 특정 플레이어만 벽을 피해 밀어내지 않으므로 대칭성과 공정한 간격이 유지된다.
    for(const ratio of radiusRatios){
      const radius=
        baseRadius*ratio;

      for(let step=0;step<72;step++){
        const rotation=
          baseRotation+
          Math.PI*2*step/72;
        const candidate=this.polygon(
          ids,
          rotation,
          radius,
          width,
          height
        );

        if(
          ids.every(pid=>
            this.pointClear(
              candidate[pid].x,
              candidate[pid].y
            )
          )
        ){
          return candidate;
        }
      }
    }

    // 비정상적으로 모든 후보가 막힌 맵에서도 정다각형 자체는 깨지지 않는다.
    return this.polygon(
      ids,
      baseRotation,
      baseRadius*.21,
      width,
      height
    );
  }
});

// 공격 태그의 원본은 판정 모듈이다. 명시 태그에는 입력/연계의 의미만 남긴다.
const attackTagMetadataCache=new WeakMap();
const TagService=Object.freeze({
  rangeTag(range){
    const value=Math.max(0,Number(range)||0);
    return GAME_DATA.ranges.find(item=>value<=item.maxInclusive)?.tag||'초장거리';
  },
  isDerivedTag(tag){
    return GAME_DATA.ranges.some(item=>item.tag===tag)||
      Object.entries(COMBAT_STATUS_DEFS).some(([id,definition])=>tag===id||tag===definition.label)||
      Object.entries(COMBAT_BUFF_DEFS).some(([id,definition])=>tag===id||tag===definition.label)||
      [
        '공격','히트스캔','범위 공격','공격형태 원','공격형태 사각','공격형태 부채꼴','공격형태 투사체',
        '일반 투사체','무기 투사체','레이저 투사체','즉발 레이저 투사체','범위 투사체','특수 투사체',
        '근접 무기','이동기','벽 관통','적 관통','유도','귀환','설치형','소환','차징','충전','채널링',
        '다중 공격','대상당 1회','넉백','무력화 넉백','끌어오기','체력 회복','스테미나 회복','보호막',
        '최대 체력 비례 피해','조건부 피해','방어','버프','은신','벽 파괴',
        // 예전 표기의 별칭도 보관된 태그에서 다시 유입시키지 않는다.
        '범위','투사체','일반','관통','근접','회복'
      ].includes(tag);
  },
  explicitAttackTags(spec){
    return new Set((spec?.tags||[]).filter(tag=>!this.isDerivedTag(tag)));
  },
  characterFor(spec){
    if(!spec?.id)return null;
    return Object.values(GAME_DATA.characters||{}).find(character=>
      Object.values(character.attacks||{}).some(attack=>attack.id===spec.id||attack.charge?.fullSpec?.id===spec.id)
    )||null;
  },
  characterMetadata(character){
    if(!character)return {fields:new Map(),channels:new Set(),combos:new Set()};
    const cached=attackTagMetadataCache.get(character);
    if(cached)return cached;
    const fields=new Map(),byState=new Map(),expansions=[],channels=new Set(),combos=new Set();
    const addField=field=>{
      if(field.removeOnly===true)return;
      if(field.stateKey&&!byState.has(field.stateKey))byState.set(field.stateKey,field);
      if(field.attackId&&field.damageOnTrigger===true){
        if(!fields.has(field.attackId))fields.set(field.attackId,[]);
        fields.get(field.attackId).push(field);
      }
    };
    const visit=value=>{
      if(!value||typeof value!=='object')return;
      if(value.type==='field.area')addField(value);
      if(value.type==='field.expand-recent')expansions.push(value);
      if(value.type==='channel.attack'&&value.attackId)channels.add(value.attackId);
      for(const child of Object.values(value))visit(child);
    };
    visit(character);
    for(const expansion of expansions){
      const original=byState.get(expansion.sourceStateKey);
      if(!original||!expansion.attackId)continue;
      addField({...original,...expansion,type:'field.area',stateKey:expansion.outputStateKey,
        damageOnTrigger:true,halfWidth:(Number(original.halfWidth)||0)*(Number(expansion.halfWidthMultiplier)||1)});
    }
    // 별도 AttackSpec으로 발사되는 콤보는 전달형태/CC를 서로 복사하지 않고 연타 의미만 공유한다.
    for(const ability of Object.values(character.abilities||{})){
      for(const trigger of Object.values(ability)){
        if(!Array.isArray(trigger?.modules))continue;
        const groups=new Map();
        for(const module of trigger.modules){
          if(module?.type!=='action.trigger-attack'||!module.attackId)continue;
          const first=module.requireAttackId||ability.attackId;
          if(!first)continue;
          if(!groups.has(first))groups.set(first,new Set([first]));
          groups.get(first).add(module.attackId);
        }
        for(const [first,ids] of groups){
          const attack=Object.values(character.attacks||{}).find(item=>item.id===first);
          const delivers=(attack?.modules||[]).some(module=>
            /^delivery\./.test(module.type)||module.type==='effect.spawn'&&module.damage
          );
          if(!delivers)ids.delete(first);
          if(ids.size>1)for(const id of ids)combos.add(id);
        }
      }
    }
    const result={fields,channels,combos};
    attackTagMetadataCache.set(character,result);
    return result;
  },
  attackRange(spec){
    if(!spec)return 0;
    const value=number=>Math.max(0,Number(number)||0);
    let range=value(spec.range);
    const readModules=modules=>{
      for(const module of modules||[]){
        if(!module||typeof module!=='object')continue;
        if(['delivery.projectile','delivery.range-projectile','delivery.area','delivery.hitscan'].includes(module.type)){
          range=Math.max(range,value(module.range));
          if(module.targetPoint===true&&module.targetPointClampToAttackRange===false)range=Infinity;
        }
        if(module.type==='effect.spawn'&&module.damage?.module)readModules([module.damage.module]);
      }
    };
    const readScale=scale=>{
      range=Math.max(range,value(scale?.range?.from),value(scale?.range?.to));
      for(const item of scale?.moduleValues||[]){
        if(item.property==='range')range=Math.max(range,value(item.from),value(item.to));
      }
    };
    readModules(spec.modules);
    readScale(spec.charge);
    readScale(spec.progressScale);
    if(spec.charge?.fullSpec)range=Math.max(range,this.attackRange(spec.charge.fullSpec));
    const character=this.characterFor(spec);
    for(const ability of Object.values(character?.abilities||{})){
      for(const trigger of Object.values(ability)){
        for(const module of trigger?.modules||[]){
          if(module.type==='counter.execute'&&ability.attackId===spec.id)readScale(module.charge);
        }
      }
    }
    return range;
  },
  addStatusTags(tags,status){
    if(!status)return;
    const id=typeof status==='string'?status:status.status;
    if(!id||typeof status==='object'&&Number(status.duration)===0)return;
    tags.add(id);
    const definition=COMBAT_STATUS_DEFS[id]||COMBAT_BUFF_DEFS[id];
    if(definition?.label)tags.add(definition.label);
    if(id==='stealth')tags.add('은신');
  },
  addBuffTags(tags,stat,value){
    if(!stat||Number(value)===0)return;
    tags.add('버프');
    tags.add(stat);
    if(COMBAT_BUFF_DEFS[stat]?.label)tags.add(COMBAT_BUFF_DEFS[stat].label);
    if(stat==='stealth')tags.add('은신');
  },
  addShapeTags(tags,shape){
    if(shape==='rect'||shape==='rectangle')tags.add('공격형태 사각');
    else if(['sector','cone','tapered-rect'].includes(shape))tags.add('공격형태 부채꼴');
    else if(shape==='circle')tags.add('공격형태 원');
  },
  fieldGeometryTags(field){
    const tags=new Set();
    if(!field||typeof field!=='object')return tags;
    tags.add('설치형');
    // 회수 명령과 다른 공격을 호출하는 감지 반경은 피해/지원 범위가 아니다.
    if(field.removeOnly===true||field.attackId&&field.damageOnTrigger!==true)return tags;
    const hasGeometry=['range','halfWidth','startHalfWidth','endHalfWidth'].some(key=>Number(field[key])>0)||field.pairWalls===true;
    if(!hasGeometry)return tags;
    tags.add('범위 공격');
    this.addShapeTags(tags,field.pairWalls?'rect':String(field.shape||'circle'));
    return tags;
  },
  derivedModuleTags(modules,{character=null,visited=new Set()}={}){
    const tags=new Set();
    const merge=items=>{
      for(const tag of this.derivedModuleTags(items,{character,visited}))tags.add(tag);
    };
    const linkModules=id=>{
      const linked=Object.values(character?.attacks||{}).find(attack=>attack.id===id);
      if(linked)merge(linked.modules);
    };
    const list=Array.isArray(modules)?modules:[];
    const projectile=list.find(module=>['delivery.projectile','delivery.range-projectile'].includes(module?.type||module));
    let scatterCount=1;
    for(const module of list){
      if(!module)continue;
      const type=typeof module==='string'?module:module.type;
      if(typeof module==='object'){
        if(visited.has(module))continue;
        visited.add(module);
      }
      if(type==='delivery.projectile'||type==='delivery.range-projectile'){
        tags.add('공격형태 투사체');
        if(type==='delivery.range-projectile'){
          // 기존 범위 투사체는 이동하는 원형 범위 판정이며 범위 증폭 대상이다.
          tags.add('범위 투사체');tags.add('히트스캔');tags.add('범위 공격');tags.add('공격형태 원');
        }
        if(module.homing)tags.add('유도');
        if(module.phase==='returning')tags.add('귀환');
      }
      if(type==='projectile.redirect')tags.add('유도');
      if(type==='projectile.wall-relay')tags.add('벽 관통');
      if(type==='delivery.hitscan'||type==='delivery.area'){
        tags.add('히트스캔');tags.add('범위 공격');
        this.addShapeTags(tags,String(module.shape||'rect'));
        if(module.wallPolicy==='ignore')tags.add('벽 관통');
        if(String(module.contactType||'').toLowerCase()==='melee')tags.add('근접 무기');
        if(module.projectileClassification==='instant-laser'){
          tags.add('공격형태 투사체');tags.add('레이저 투사체');tags.add('즉발 레이저 투사체');
        }
        if(Number(module.repeatCount??module.repeat?.count)>1)tags.add('다중 공격');
      }
      if(type==='field.area'){
        for(const tag of this.fieldGeometryTags(module))tags.add(tag);
        if(module.removeOnly!==true){
          merge(module.onTrigger);
          if(module.wallPolicy==='ignore'&&tags.has('범위 공격'))tags.add('벽 관통');
        }
      }
      if(type==='effect.spawn'&&module.damage){
        const damage=module.damage;
        if(damage.module)merge([damage.module]);
        if(damage.hitMode==='body-contact'){
          // 현재 본체 원의 접촉/실제 이동 선분을 검사한다. 선행 사각 히트스캔이 아니다.
          tags.add('범위 공격');tags.add('공격형태 원');
        }
        if(damage.oncePerExecution===true)tags.add('대상당 1회');
        if(damage.projectileClear)tags.add('방어');
      }
      if(type==='movement.move'){
        // 자가 반동은 이동기나 적에게 주는 넉백으로 분류하지 않는다.
        if(module.motionMode!=='knockback'){
          tags.add('이동기');
          const collision=MovementAbilityService.normalizeCollision(module);
          if(collision.passWalls)tags.add('벽 관통');
          if(collision.passEnemies)tags.add('적 관통');
        }
      }
      if(['movement.stationary-projectile-swap','projectile.ride.start'].includes(type))tags.add('이동기');
      if(type==='projectile.impact'){
        if(module.field)merge([module.field]);
        if(module.sourceRelocate)merge([{...module.sourceRelocate,type:'movement.move',tags:[]}]);
        if(module.summon)tags.add('소환');
        // 별도 impact AttackSpec의 전달형태/CC는 그 공격이 직접 조회될 때만 계산한다.
      }
      if(type==='projectile.pierce'){
        if(module.targets)tags.add('적 관통');
        if(module.walls)tags.add('벽 관통');
      }
      if(type==='hit.sequence'){
        for(const step of module.steps||[])merge(step.modules);
      }
      if(type==='delivery.delayed-projectile-volley'){
        if(module.attackId)linkModules(module.attackId);
      }
      if(type==='state.progress'||type==='state.progress-rate'){
        if(!['subtract','reset'].includes(module.operation)&&Number(module.amount)!==0)tags.add('충전');
        this.addStatusTags(tags,module.onFull);
      }
      if(type==='resource.restore'){
        if(module.resource==='health')tags.add('체력 회복');
        if(module.resource==='stamina')tags.add('스테미나 회복');
        if(module.resource==='shield')tags.add('보호막');
      }
      if(type==='modifier.set')this.addBuffTags(tags,module.stat,module.value);
      if(type==='status.apply'&&module.target!=='self'&&module.target!=='source')this.addStatusTags(tags,module);
      if(type==='damage.target-max-health-ratio')tags.add('최대 체력 비례 피해');
      if(type==='damage.range-band-multiplier'||type==='damage.target-health-ratio-multiplier'||type==='damage.target-status-multiplier')tags.add('조건부 피해');
      if(type==='attack.guard')tags.add('방어');
      if(type==='world.destroy-walls')tags.add('벽 파괴');
      if(type==='hit.once-per-execution')tags.add('대상당 1회');
      if(['movement.knockback','movement.neutralize-knockback'].includes(type)&&module.target==='hit-target'){
        tags.add('넉백');
        if(type==='movement.neutralize-knockback'){
          tags.add('무력화 넉백');this.addStatusTags(tags,'neutralize');
        }
        this.addStatusTags(tags,module.wallImpactStatus);
      }
      if(type==='movement.pull'||type==='movement.projectile-tether'){
        tags.add('끌어오기');
        this.addStatusTags(tags,module.status);
      }
      if(type==='pattern.scatter'||type==='delivery.delayed-projectile-volley')scatterCount=Math.max(scatterCount,Number(module.count)||1);
      if(type==='buff.time-add'){
        tags.add('버프');
        if(Number(module.aura?.range)>0){tags.add('범위 공격');tags.add('공격형태 원');}
        for(const stage of module.stages||[])this.addBuffTags(tags,stage.stat,stage.value);
      }
      if(type==='sustain.toggle')for(const buff of module.buffs||[])this.addBuffTags(tags,buff.type,buff.value);
      if(type==='stealth.toggle'){this.addBuffTags(tags,'stealth',1);}
      if(type==='channel.attack')tags.add('채널링');
      if(['summon.spawn','summon.cluster-spawn','summon.toggle','summon.recall','summon.return-owner','summon.retarget'].includes(type))tags.add('소환');
      if(type==='field.expand-recent')tags.add('설치형');
      if(type==='formation.place-minimum'||type==='obstacle.wall-deploy')tags.add('설치형');
      if(type==='formation.manifest'){
        tags.add('범위 공격');tags.add('히트스캔');tags.add('공격형태 원');
        for(const status of ['slow','bind','freeze'])this.addStatusTags(tags,status);
      }
      // 모듈의 의미 태그만 병합한다. 계산 태그를 수동 값으로 덮어쓰지 않는다.
      for(const tag of this.explicitAttackTags(module))tags.add(tag);
    }
    if(scatterCount>1)tags.add('다중 공격');
    if(projectile&&(projectile.type||projectile)!=='delivery.range-projectile'){
      const presentation=list.find(module=>module?.type==='projectile.presentation');
      const collision=list.find(module=>module?.type==='projectile.collision');
      if(presentation?.kind==='weapon-projectile')tags.add('무기 투사체');
      else if(presentation?.style?.type==='laser-bolt')tags.add('레이저 투사체');
      else if(presentation?.style?.shape==='diamond'||collision?.shape==='diamond'||scatterCount>1&&list.some(module=>module?.type==='hit.once-per-execution'))tags.add('특수 투사체');
      else tags.add('일반 투사체');
    }
    return tags;
  },
  linkedAbilityModuleTags(spec,character=this.characterFor(spec)){
    const tags=new Set();
    const merge=modules=>{
      for(const tag of this.derivedModuleTags(modules,{character}))tags.add(tag);
    };
    for(const ability of Object.values(character?.abilities||{})){
      for(const trigger of Object.values(ability)){
        const modules=trigger?.modules;
        if(!Array.isArray(modules))continue;
        const direct=ability.attackId===spec.id||ability.holdAttackId===spec.id||
          (ability.inputAttackAlternates||[]).some(item=>item.attackId===spec.id);
        const hasDelivery=(spec.modules||[]).some(module=>
          /^delivery\./.test(module?.type)||module?.type==='effect.spawn'&&module.damage||module?.type==='formation.manifest'
        );
        const selected=direct||modules.some(module=>
          module.requireAttackId===spec.id||module.alternateWhen?.attackId===spec.id||
          (module.alternates||[]).some(item=>item.attackId===spec.id)
        );
        if(!selected)continue;
        for(const module of modules){
          if(module.requireAttackId&&module.requireAttackId!==spec.id)continue;
          if(module.type==='counter.execute'){
            const alternate=module.alternateWhen?.attackId===spec.id?module.alternateWhen:null;
            if(!direct&&!alternate)continue;
            const cc=alternate?.cc||module.cc;
            if(cc)merge(Array.isArray(cc)?cc:[cc]);
            if(module.charge)tags.add('차징');
          }else if(module.type==='charge.attack.start'||module.type==='charge.attack.release'){
            if(spec.charge||spec.multiClick)tags.add('차징');
          }else{
            // 입력 선딜·무적·버프·이동은 AttackSpec의 판정 태그가 아니다.
            // 실제 피해/CC는 해당 AttackSpec의 modules 또는 counter.execute.cc에만 둔다.
            continue;
          }
        }
      }
    }
    const metadata=this.characterMetadata(character);
    if(metadata.channels.has(spec.id))tags.add('채널링');
    if(metadata.combos.has(spec.id))tags.add('다중 공격');
    for(const field of metadata.fields.get(spec.id)||[])merge([field]);
    return tags;
  },
  derivedAttackTags(spec){
    const tags=new Set();
    if(!spec)return tags;
    tags.add('공격');
    const range=this.attackRange(spec);
    if(range>0)tags.add(this.rangeTag(range));
    if(spec.charge||spec.multiClick)tags.add('차징');
    const character=this.characterFor(spec);
    for(const tag of this.derivedModuleTags(spec.modules,{character}))tags.add(tag);
    for(const tag of this.linkedAbilityModuleTags(spec,character))tags.add(tag);
    return tags;
  },
  attackTags(spec){
    if(!spec||typeof spec!=='object')return new Set();
    const cached=attackTagCache.get(spec);
    if(cached)return cached;
    const tags=this.explicitAttackTags(spec);
    for(const tag of this.derivedAttackTags(spec))tags.add(tag);
    attackTagCache.set(spec,tags);
    return tags;
  },
  isCrowdControlAttack(spec){
    if(!spec)return false;
    const tags=this.attackTags(spec);
    return Object.entries(COMBAT_STATUS_DEFS).some(([status,definition])=>definition.kind==='cc'&&tags.has(status))||tags.has('넉백')||tags.has('끌어오기');
  },
  fieldTags(field){
    if(!field||typeof field!=='object')return new Set();
    const tags=this.derivedModuleTags([{...field,type:'field.area'}]);
    if((field.targetRelations||[]).some(relation=>relation==='ally'||relation==='self'))tags.add('아군 대상');
    return tags;
  },
  primaryAttackRange(character){
    let maxRange=null;

    for(const spec of Object.values(character?.attacks||{})){
      if(!spec?.tags?.includes('평타'))continue;

      const range=this.attackRange(spec);
      maxRange=maxRange===null
        ?range
        :Math.max(maxRange,range);
    }

    return maxRange;
  },
  characterTags(character){
    const tags=new Set(character?.tags||[]);
    const range=CharacterSortService.distanceTag(character);
    if(range)tags.add(range);
    return tags;
  },
  characterStyleLabel(character){
    return CharacterSortService.styleLabel(character);
  },
  hasAttack(spec,tag){
    return this.attackTags(spec).has(tag);
  },
  effectTags(effect){
    const tags=new Set(effect?.tags||[]);
    if(!effect)return tags;

    if(effect.type==='modifier.constant'){
      const value=Number(effect.value)||0;
      if(value>0)tags.add('증강 버프');
      if(value<0)tags.add('증강 디버프');
    }

    if(effect.type==='trigger'){
      for(const module of effect.modules||[]){
        if(module?.type==='status.apply'&&module.status){
          tags.add(module.status);
          const label=COMBAT_STATUS_DEFS[module.status]?.label;
          if(label)tags.add(label);
        }
        if(module?.type==='resource.restore'){
          if(module.resource==='health')tags.add('체력 회복');
          if(module.resource==='stamina')tags.add('스테미나 회복');
        }
        if(module?.type==='modifier.set'){
          const value=Number(module.value)||0;
          if(value>0)tags.add('증강 버프');
          if(value<0)tags.add('증강 디버프');
        }
        if(module?.type==='damage.multiply'&&Number(module.value)<1){
          tags.add('피해 감소');
        }
        if(module?.type==='defeat.prevent')tags.add('생존');
        if(module?.type==='attack.trigger'&&module.attack){
          for(const tag of this.attackTags(module.attack))tags.add(tag);
        }
      }
    }

    return tags;
  },
});


const AttackQueryService=Object.freeze({
  rangeRank(tag){
    return GAME_DATA.ranges.findIndex(
      item=>item.tag===tag
    );
  },
  matchesTags(tags,selector){
    if(!selector)return false;
    const resolvedTags=
      tags instanceof Set
        ?tags
        :new Set(tags||[]);

    if(Array.isArray(selector.any)){
      return selector.any.some(
        item=>this.matchesTags(
          resolvedTags,
          item
        )
      );
    }

    for(const tag of selector.tags||[]){
      if(!resolvedTags.has(tag)){
        return false;
      }
    }

    return true;
  },
  matchesSelector(spec,selector){
    if(!spec||!selector)return false;

    if(
      !this.matchesTags(
        TagService.attackTags(spec),
        selector
      )
    )return false;

    if(selector.maxRangeTag){
      const actual=
        this.rangeRank(
          TagService.rangeTag(
            TagService.attackRange(spec)
          )
        );
      const maximum=
        this.rangeRank(
          selector.maxRangeTag
        );

      if(
        actual<0||
        maximum<0||
        actual>maximum
      )return false;
    }

    return true;
  },
  minimumCost(character,tag='공격'){
    let minimum=Infinity;

    for(const attack of Object.values(
      character?.attacks||{}
    )){
      if(!TagService.hasAttack(attack,tag))continue;

      minimum=Math.min(
        minimum,
        Math.max(0,Number(attack.cost)||0)
      );
    }

    return Number.isFinite(minimum)
      ?minimum
      :0;
  }
});

